    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 16, 'Từ trên hướng dẫn thi và phiếu đáp án', '筆記用具', 'ひっきようぐ', 'Dụng cụ viết 筆記用具を確認して、', '記録します。', 'ひっきようぐをかくにんして、きろくします。', 'Kiểm tra và ghi lại dụng cụ viết.', 488);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 16, 'Từ trên hướng dẫn thi và phiếu đáp án', '不鮮明', 'ふせんめい', 'Không rõ nét 印刷が不鮮明な場合は、', '係員に知らせます。', 'いんさつがふせんめいなばあいは、かかりいんにしらせます。', 'Báo cho cán bộ coi thi nếu bản in không rõ nét.', 489);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 16, 'Từ trên hướng dẫn thi và phiếu đáp án', '問題', 'もんだい', 'Câu hỏi; đề bài', '問題をよく読みます。', 'もんだいをよくよみます。', 'Đọc kỹ câu hỏi.', 490);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 16, 'Từ trên hướng dẫn thi và phiếu đáp án', 'マークシート', 'マークシート', 'Phiếu tô đáp án', 'マークシートに答えを記入します。', 'マークシートにこたえをきにゅうします。', 'Điền đáp án vào phiếu tô đáp án. Danh sách PDF đã đọc - 2023_3kyu_kikai_kaitou1.pdf - 2023_3kyu_kikai_mondai1.pdf - 2023__3kyu_kikai_kaitou_2.pdf - 2023__3kyu_kikai_mondai_2.pdf - 2024_3kyu_kikai_kaitou_1.pdf - 2024_3kyu_kikai_kaitou_2.pdf - 2024_3kyu_kikai_mondai_1.pdf - 2024_3kyu_kikai_mondai_2.pdf - 2025_3kyu_kikai_kaitou_1.pdf - 2025_3kyu_kikai_kaitou_2.pdf - 2025_3kyu_kikai_mondai_1.pdf - 2025_3kyu_kikai_mondai_2.pdf - 2026_3kyu_kikai_kaitou1.pdf - 2026_3kyu_kikai_mondai1.pdf PDF sách đã xuất và PDF bìa không tính là nguồn độc lập vì là bản biên soạn từ các đề trên. CNC không có chương riêng vì các đề này không chứa đủ thuật ngữ lập trình CNC để lọc thành một nhóm.', 491);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 1, '下図に示す工作機械は、フライス盤である。', 'Máy công cụ trong hình dưới là máy phay.', TRUE, 'Hình có bàn máy và cụm trục chính phục vụ cắt bằng dao phay: đó là フライス盤. Máy phay gia công các mặt hoặc rãnh bằng dụng cụ cắt quay và chuyển động chạy dao tương đối. Vì vậy nhận định trong đề đúng.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}, {"term": "フライス盤", "reading": "フライスばん", "meaning": "Máy phay"}]'::jsonb, 1);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 2, 'ボール盤とは、工作物を主軸に取り付け、工作物を回転させながら加工を行う工作機械であ る。', 'Máy khoan là máy công cụ gia công bằng cách gắn phôi vào trục chính và cho phôi quay.', FALSE, 'Nội dung này mô tả máy tiện, không phải máy khoan. Ở máy khoan thông thường, phôi được gá cố định và mũi khoan gắn trên trục chính quay để tạo lỗ. Từ sai trong đề là 工作物を回転させる — cho phôi quay.', '[{"term": "ボール盤", "reading": "ボールばん", "meaning": "Máy khoan"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "Phôi; vật gia công"}, {"term": "主軸", "reading": "しゅじく", "meaning": "Trục chính"}, {"term": "取り付け", "reading": "とりつけ", "meaning": "Lắp; gắn (dạng nối câu của 取り付ける)"}, {"term": "回転", "reading": "かいてん", "meaning": "Chuyển động quay"}, {"term": "させながら", "reading": "させながら", "meaning": "Vừa cho/làm cho… vừa…"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}]'::jsonb, 2);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 3, '下図に示す回路における抵抗Rは、10Ωである。', 'Điện trở R trong mạch dưới là 10 Ω.', FALSE, 'Nguồn 10 V tạo dòng 1 A, nên điện trở toàn mạch Rt = U/I = 10/1 = 10 Ω. R mắc nối tiếp với điện trở 5 Ω, do đó R + 5 = 10 và R = 5 Ω. Đề nhầm điện trở toàn mạch với điện trở R cần tìm.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "回路", "reading": "かいろ", "meaning": "Mạch điện; mạch hệ thống, tùy ngữ cảnh"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "抵抗", "reading": "ていこう", "meaning": "Điện trở trong câu mạch điện"}, {"term": "Ω", "reading": "オーム", "meaning": "Ôm; đơn vị điện trở"}]'::jsonb, 3);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 4, '三相誘導電動機は、3本の電源線のうち、いずれかの2本の接続を入れ替えると電動機の軸の 回転方向が逆になる。', 'Với động cơ không đồng bộ ba pha, đổi chỗ kết nối của bất kỳ hai trong ba dây nguồn sẽ đảo chiều quay trục động cơ.', TRUE, 'Đổi chỗ hai pha làm đảo thứ tự pha và đảo chiều từ trường quay, nên động cơ đổi chiều quay. Đây là nguyên lý đối với động cơ cấp nguồn ba pha theo cấu hình thông thường; không phải hướng dẫn tự ý đổi dây khi đang có điện.', '[{"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "Động cơ không đồng bộ ba pha"}, {"term": "電源線", "reading": "でんげんせん", "meaning": "Dây nguồn điện"}, {"term": "のうち", "reading": "のうち", "meaning": "Trong số…"}, {"term": "接続", "reading": "せつぞく", "meaning": "Kết nối; đấu nối"}, {"term": "入れ替える", "reading": "いれかえる", "meaning": "Đổi chỗ; thay đổi vị trí cho nhau"}, {"term": "電動機", "reading": "でんどうき", "meaning": "Động cơ điện"}, {"term": "軸", "reading": "じく", "meaning": "Trục"}, {"term": "回転方向", "reading": "かいてんほうこう", "meaning": "Chiều quay"}, {"term": "逆", "reading": "ぎゃく", "meaning": "Ngược"}, {"term": "になる", "reading": "になる", "meaning": "Trở thành; thay đổi thành"}]'::jsonb, 4);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 5, '事後保全とは、設備に故障が発生した段階で、その故障を取り除く保全活動である。', 'Bảo trì sau hỏng là hoạt động loại bỏ sự cố tại thời điểm thiết bị đã phát sinh hỏng.', TRUE, '事後保全 thực hiện sau khi hỏng xảy ra để sửa chữa hoặc khôi phục chức năng. Nó khác với bảo trì phòng ngừa trước khi hỏng. Cụm 故障が発生した段階 — giai đoạn đã phát sinh hỏng là dấu hiệu để nhận dạng.', '[{"term": "事後保全", "reading": "じごほぜん", "meaning": "Bảo trì sau khi hỏng"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "段階", "reading": "だんかい", "meaning": "Giai đoạn; thời điểm"}, {"term": "取り除く", "reading": "とりのぞく", "meaning": "Loại bỏ"}, {"term": "保全活動", "reading": "ほぜんかつどう", "meaning": "Hoạt động bảo trì"}]'::jsonb, 5);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 6, '故障モードの例として、変形や腐食などが挙げられる。', 'Các ví dụ về dạng hỏng gồm biến dạng, ăn mòn và những dạng khác.', TRUE, '故障モード mô tả kiểu hoặc biểu hiện hỏng của đối tượng, ví dụ biến dạng hoặc ăn mòn. Nó khác với 故障原因, là nguyên nhân dẫn đến hỏng. Vì vậy các ví dụ nêu trong đề phù hợp.', '[{"term": "故障モード", "reading": "こしょうモード", "meaning": "Dạng hỏng; kiểu biểu hiện hỏng"}, {"term": "例", "reading": "れい", "meaning": "Ví dụ"}, {"term": "変形", "reading": "へんけい", "meaning": "Biến dạng"}, {"term": "腐食", "reading": "ふしょく", "meaning": "Ăn mòn"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 6);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 7, '下図のバスタブ曲線において、Ａは摩耗故障期、Ｂは偶発故障期である。', 'Trong đường cong bồn tắm dưới đây, A là giai đoạn hỏng do hao mòn và B là giai đoạn hỏng ngẫu nhiên.', FALSE, 'Hình cho thấy A ở đoạn giữa gần nằm ngang, là 偶発故障期 — giai đoạn hỏng ngẫu nhiên; B ở đoạn cuối tăng lên, là 摩耗故障期 — giai đoạn hỏng do hao mòn. Đề đã đảo hai nhãn. Đoạn đầu giảm dần là 初期故障期 — giai đoạn hỏng ban đầu.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "バスタブ曲線", "reading": "バスタブきょくせん", "meaning": "Đường cong bồn tắm"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "摩耗故障期", "reading": "まもうこしょうき", "meaning": "Giai đoạn hỏng do hao mòn"}, {"term": "偶発故障期", "reading": "ぐうはつこしょうき", "meaning": "Giai đoạn hỏng ngẫu nhiên"}]'::jsonb, 7);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 8, '設備履歴簿には、設備の故障の内容や、修理に要した費用などの記録を残す。', 'Sổ lịch sử thiết bị ghi lại nội dung hỏng và các thông tin như chi phí cần cho sửa chữa.', TRUE, '設備履歴簿 giúp lưu dấu quá trình vận hành, hỏng và sửa chữa. Thông tin về nội dung sự cố và chi phí sửa là dữ liệu thích hợp để theo dõi và lập kế hoạch bảo trì. Vì vậy câu đúng.', '[{"term": "設備履歴簿", "reading": "せつびりれきぼ", "meaning": "Sổ lịch sử thiết bị"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "内容", "reading": "ないよう", "meaning": "Nội dung"}, {"term": "修理", "reading": "しゅうり", "meaning": "Sửa chữa"}, {"term": "要した", "reading": "ようした", "meaning": "Đã cần/đã tốn (dạng của 要する)"}, {"term": "費用", "reading": "ひよう", "meaning": "Chi phí"}, {"term": "記録", "reading": "きろく", "meaning": "Ghi chép; bản ghi"}, {"term": "残す", "reading": "のこす", "meaning": "Lưu lại; để lại"}]'::jsonb, 8);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 9, '下図は、特性要因図である。', 'Hình dưới là biểu đồ nguyên nhân–kết quả.', FALSE, 'Hình thực tế là パレート図 — biểu đồ Pareto, gồm các cột xếp theo thứ tự giảm và đường tích lũy. 特性要因図 có dạng xương cá với các nhánh nguyên nhân, khác hình này. Không chỉ nhìn lời đề mà cần nhận dạng cấu trúc biểu đồ.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "Biểu đồ nguyên nhân–kết quả; biểu đồ"}]'::jsonb, 9);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 10, '作業標準書とは、作業者が作業にかかった時間を、作業のたびに記入するものである。', 'Bản tiêu chuẩn thao tác là tài liệu để người lao động ghi thời gian thực hiện sau mỗi lần làm việc.', FALSE, '作業標準書 quy định phương pháp, trình tự, điều kiện và điểm cần chú ý để làm công việc nhất quán. Tài liệu ghi thời gian mỗi lần làm là bản ghi thực hiện/thời gian công việc. Chỗ sai là nhầm tài liệu hướng dẫn chuẩn với tài liệu ghi kết quả.', '[{"term": "作業標準書", "reading": "さぎょうひょうじゅんしょ", "meaning": "Bản tiêu chuẩn/hướng dẫn thao tác"}, {"term": "作業者", "reading": "さぎょうしゃ", "meaning": "Người thực hiện công việc"}, {"term": "作業", "reading": "さぎょう", "meaning": "Công việc; thao tác"}, {"term": "かかった時間", "reading": "かかったじかん", "meaning": "Thời gian đã mất/đã dùng"}, {"term": "たびに", "reading": "たびに", "meaning": "Mỗi khi; mỗi lần"}, {"term": "記入", "reading": "きにゅう", "meaning": "Điền; ghi vào"}]'::jsonb, 10);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 11, '鉄は、銅よりも耐食性に優れる。', 'Sắt chống ăn mòn tốt hơn đồng.', FALSE, 'Trong so sánh cơ bản ở môi trường thông thường, sắt dễ gỉ hơn đồng. Khả năng chống ăn mòn còn phụ thuộc môi trường và thành phần vật liệu, nhưng nhận định tổng quát của đề là sai. Không đồng nhất sắt thông thường với thép không gỉ.', '[{"term": "鉄", "reading": "てつ", "meaning": "Sắt"}, {"term": "銅", "reading": "どう", "meaning": "Đồng"}, {"term": "より", "reading": "より", "meaning": "So với; hơn (dùng khi so sánh)"}, {"term": "耐食性", "reading": "たいしょくせい", "meaning": "Khả năng chống ăn mòn"}, {"term": "優れる", "reading": "すぐれる", "meaning": "Vượt trội; tốt hơn"}]'::jsonb, 11);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 12, 'ステンレス鋼は、鉄と亜鉛の合金である。', 'Thép không gỉ là hợp kim của sắt và kẽm.', FALSE, 'Nguyên tố đặc trưng tạo tính không gỉ là crôm, không phải kẽm. Một số nhóm có thêm niken hoặc các nguyên tố khác để đạt tính chất mong muốn. Vì vậy cách định nghĩa trong đề sai.', '[{"term": "ステンレス鋼", "reading": "ステンレスこう", "meaning": "Thép không gỉ"}, {"term": "鉄", "reading": "てつ", "meaning": "Sắt"}, {"term": "亜鉛", "reading": "あえん", "meaning": "Kẽm"}, {"term": "合金", "reading": "ごうきん", "meaning": "Hợp kim"}]'::jsonb, 12);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 13, '金属の熱処理は、加熱温度や冷却速度などを調節することにより、性質や金属組織を改良す る加工方法である。', 'Nhiệt luyện kim loại là phương pháp cải thiện tính chất và tổ chức kim loại bằng điều chỉnh nhiệt độ gia nhiệt, tốc độ làm nguội và các điều kiện khác.', TRUE, '熱処理 dùng chế độ nhiệt phù hợp để thay đổi tổ chức và tính chất vật liệu. Tôi, ram, ủ và thường hóa là những ví dụ. Đề mô tả nguyên lý chung đúng.', '[{"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "熱処理", "reading": "ねつしょり", "meaning": "Nhiệt luyện"}, {"term": "加熱温度", "reading": "かねつおんど", "meaning": "Nhiệt độ gia nhiệt"}, {"term": "冷却速度", "reading": "れいきゃくそくど", "meaning": "Tốc độ làm nguội"}, {"term": "調節", "reading": "ちょうせつ", "meaning": "Điều chỉnh"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "性質", "reading": "せいしつ", "meaning": "Tính chất"}, {"term": "金属組織", "reading": "きんぞくそしき", "meaning": "Tổ chức kim loại"}, {"term": "改良", "reading": "かいりょう", "meaning": "Cải tiến; cải thiện"}, {"term": "加工方法", "reading": "かこうほうほう", "meaning": "Phương pháp gia công"}]'::jsonb, 13);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 14, '労働安全衛生法は、労働者の安全と健康を確保するために、事業主等の責任を定めた法律で ある。', 'Luật An toàn và Vệ sinh lao động là luật quy định trách nhiệm của chủ sử dụng lao động và các bên nhằm bảo đảm an toàn, sức khỏe người lao động.', TRUE, '労働安全衛生法 có mục tiêu bảo đảm an toàn và sức khỏe của người lao động, đồng thời quy định trách nhiệm liên quan. Mệnh đề nêu đúng mục tiêu cơ bản. Mục đích của luật — MHLW', '[{"term": "労働安全衛生法", "reading": "ろうどうあんぜんえいせいほう", "meaning": "Luật An toàn và Vệ sinh lao động"}, {"term": "労働者", "reading": "ろうどうしゃ", "meaning": "Người lao động"}, {"term": "安全", "reading": "あんぜん", "meaning": "An toàn"}, {"term": "健康", "reading": "けんこう", "meaning": "Sức khỏe"}, {"term": "確保", "reading": "かくほ", "meaning": "Bảo đảm"}, {"term": "事業主", "reading": "じぎょうぬし", "meaning": "Chủ sử dụng lao động; người chủ cơ sở"}, {"term": "責任", "reading": "せきにん", "meaning": "Trách nhiệm"}, {"term": "定めた", "reading": "さだめた", "meaning": "Đã quy định/đặt ra (dạng của 定める)"}, {"term": "法律", "reading": "ほうりつ", "meaning": "Luật"}]'::jsonb, 14);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 15, '5Sにおける整理とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, sàng lọc là phân chia thứ cần và không cần rồi loại bỏ thứ không cần.', TRUE, 'Đây là 整理 — sàng lọc. 整頓 là sắp xếp những thứ cần thiết để dễ tìm, lấy và trả lại. Đề dùng đúng tên 整理 nên đáp án đúng.', '[{"term": "5S", "reading": "ごエス", "meaning": "5S: sàng lọc, sắp xếp, sạch sẽ, duy trì sạch"}, {"term": "sẽ,", "reading": "rèn", "meaning": "nề nếp"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "整理", "reading": "せいり", "meaning": "Sàng lọc; phân loại và bỏ thứ không cần"}, {"term": "必要", "reading": "ひつよう", "meaning": "Cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "Không cần thiết"}, {"term": "区分", "reading": "くぶん", "meaning": "Phân chia; phân loại"}, {"term": "なくす", "reading": "なくす", "meaning": "Loại bỏ; làm cho không còn"}]'::jsonb, 15);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 16, 'ねじのリードとは、ねじを1回転させたときに、ねじが軸方向に動く距離のことである。', 'Bước tiến của ren là khoảng cách ren di chuyển theo phương trục khi quay một vòng.', TRUE, 'リード là lượng tiến theo trục sau một vòng quay. Với ren một đầu mối, bước tiến bằng bước ren ピッチ; ren nhiều đầu mối có bước tiến bằng bước ren nhân số đầu mối. Định nghĩa trong đề đúng.', '[{"term": "ねじ", "reading": "ねじ", "meaning": "Ren; vít, tùy ngữ cảnh"}, {"term": "リード", "reading": "リード", "meaning": "Bước tiến của ren sau một vòng quay"}, {"term": "回転", "reading": "かいてん", "meaning": "Chuyển động quay"}, {"term": "軸方向", "reading": "じくほうこう", "meaning": "Phương dọc trục"}, {"term": "動く", "reading": "うごく", "meaning": "Chuyển động"}, {"term": "距離", "reading": "きょり", "meaning": "Khoảng cách; quãng đường"}]'::jsonb, 16);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 17, 'かさ歯車は、噛み合った2つの歯車の軸が平行な歯車である。', 'Bánh răng côn là loại có hai trục của hai bánh răng ăn khớp song song.', FALSE, 'かさ歯車 dùng cho các trục giao nhau, thường gặp góc 90° nhưng có thể là góc khác theo thiết kế. Truyền giữa trục song song là đặc trưng của bộ bánh răng trụ. Chỗ sai là 平行 — song song.', '[{"term": "かさ歯車", "reading": "かさはぐるま", "meaning": "Bánh răng côn"}, {"term": "噛み合った", "reading": "かみあった", "meaning": "Đã ăn khớp (dạng của 噛み合う)"}, {"term": "歯車", "reading": "はぐるま", "meaning": "Bánh răng"}, {"term": "軸", "reading": "じく", "meaning": "Trục"}, {"term": "平行", "reading": "へいこう", "meaning": "Song song"}]'::jsonb, 17);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 18, '測定範囲が0～25mmの外側マイクロメータを保管するときは、アンビルとスピンドルの間 にすき間を空けておく。', 'Khi cất panme đo ngoài có phạm vi 0–25 mm, để một khe hở giữa đầu đo cố định và trục đo di động.', TRUE, 'Để hai mặt đo không ép chặt khi bảo quản giúp tránh giữ lực tiếp xúc không cần thiết và hạn chế ảnh hưởng của thay đổi nhiệt độ. アンビル là đầu đo cố định, スピンドル là trục đo di động. Câu nêu cách bảo quản phù hợp.', '[{"term": "測定範囲", "reading": "そくていはんい", "meaning": "Phạm vi đo"}, {"term": "外側マイクロメータ", "reading": "そとがわマイクロメータ", "meaning": "Panme đo ngoài"}, {"term": "保管", "reading": "ほかん", "meaning": "Bảo quản; cất giữ"}, {"term": "アンビル", "reading": "アンビル", "meaning": "Đầu đo cố định của panme"}, {"term": "スピンドル", "reading": "スピンドル", "meaning": "Trục đo di động của panme"}, {"term": "間", "reading": "あいだ", "meaning": "Khoảng giữa"}, {"term": "すき間", "reading": "すきま", "meaning": "Khe hở"}, {"term": "空けておく", "reading": "あけておく", "meaning": "Để chừa khoảng trống/khe hở"}]'::jsonb, 18);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 19, '軸受に発生する腐食の原因の1つとして、使用時の過大荷重が挙げられる。', 'Một nguyên nhân gây ăn mòn ổ trục là tải quá lớn trong khi sử dụng.', FALSE, 'Ăn mòn thường liên quan độ ẩm, nước hoặc môi trường hóa học. Tải quá lớn chủ yếu gây hư hại cơ học, không phải nguyên nhân ăn mòn được hỏi ở đây. Đề nhầm giữa tải cơ học và yếu tố gây ăn mòn.', '[{"term": "軸受", "reading": "じくうけ", "meaning": "Ổ trục; ổ đỡ"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "腐食", "reading": "ふしょく", "meaning": "Ăn mòn"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "使用", "reading": "しよう", "meaning": "Sử dụng"}, {"term": "過大荷重", "reading": "かだいかじゅう", "meaning": "Tải quá lớn"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 19);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 20, '一般的に、潤滑油の粘度は、温度が上昇すると減少する。', 'Thông thường, độ nhớt dầu bôi trơn giảm khi nhiệt độ tăng.', TRUE, 'Dầu thường đặc hơn khi lạnh và loãng hơn khi nóng. Do đó 温度が上昇 — nhiệt độ tăng đi cùng 粘度が減少 — độ nhớt giảm. Nhớ phân biệt độ nhớt ở một nhiệt độ với chỉ số độ nhớt, là mức độ nhạy với thay đổi nhiệt độ.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "潤滑油", "reading": "じゅんかつゆ", "meaning": "Dầu bôi trơn"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "温度", "reading": "おんど", "meaning": "Nhiệt độ"}, {"term": "上昇", "reading": "じょうしょう", "meaning": "Tăng lên"}, {"term": "減少", "reading": "げんしょう", "meaning": "Giảm"}]'::jsonb, 20);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 21, 'アーク溶接とは、2つの母材の接合部分を燃焼ガスの炎で加熱して溶融することで、接合す る方法である。', 'Hàn hồ quang là phương pháp nối hai vật liệu cơ bản bằng cách dùng ngọn lửa khí cháy làm nóng chảy phần nối.', FALSE, 'アーク溶接 dùng nhiệt của hồ quang điện. Gia nhiệt bằng ngọn lửa khí cháy là ガス溶接 — hàn khí. Đề đã gán nguyên lý hàn khí cho hàn hồ quang.', '[{"term": "アーク溶接", "reading": "アークようせつ", "meaning": "Hàn hồ quang"}, {"term": "母材", "reading": "ぼざい", "meaning": "Vật liệu cơ bản/vật liệu nền được nối"}, {"term": "接合部分", "reading": "せつごうぶぶん", "meaning": "Vị trí/phần nối"}, {"term": "燃焼ガス", "reading": "ねんしょうガス", "meaning": "Khí cháy"}, {"term": "炎", "reading": "ほのお", "meaning": "Ngọn lửa"}, {"term": "加熱", "reading": "かねつ", "meaning": "Gia nhiệt"}, {"term": "溶融", "reading": "ようゆう", "meaning": "Nóng chảy"}, {"term": "接合", "reading": "せつごう", "meaning": "Nối; ghép"}, {"term": "方法", "reading": "ほうほう", "meaning": "Phương pháp"}]'::jsonb, 21);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 22, 'ダイスは、おねじの加工に用いる切削工具である。', 'Bàn ren là dụng cụ cắt dùng gia công ren ngoài.', TRUE, 'ダイス dùng tạo ren ngoài trên bề mặt ngoài, thường gặp ở thanh tròn. タップ — tarô dùng gia công ren trong của lỗ. Vì vậy nhận định đúng.', '[{"term": "ダイス", "reading": "ダイス", "meaning": "Bàn ren; trong câu này dùng gia công ren"}, {"term": "おねじ", "reading": "おねじ", "meaning": "Ren ngoài"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "用いる", "reading": "もちいる", "meaning": "Dùng; sử dụng"}, {"term": "切削工具", "reading": "せっさくこうぐ", "meaning": "Dụng cụ cắt"}]'::jsonb, 22);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 23, '非破壊検査には、内部欠陥を対象にするものと、表層部欠陥を対象にするものがある。', 'Trong kiểm tra không phá hủy, có phương pháp kiểm tra khuyết tật bên trong và có phương pháp kiểm tra khuyết tật vùng bề mặt.', TRUE, 'Các phương pháp kiểm tra không phá hủy có phạm vi phát hiện khác nhau. Ví dụ siêu âm hoặc chụp xuyên tia có thể khảo sát bên trong; thẩm thấu dùng cho khuyết tật hở bề mặt. Phải chọn phương pháp phù hợp vật liệu và dạng khuyết tật.', '[{"term": "非破壊検査", "reading": "ひはかいけんさ", "meaning": "Kiểm tra không phá hủy"}, {"term": "内部欠陥", "reading": "ないぶけっかん", "meaning": "Khuyết tật bên trong"}, {"term": "対象", "reading": "たいしょう", "meaning": "Đối tượng; mục tiêu"}, {"term": "表層部欠陥", "reading": "ひょうそうぶけっかん", "meaning": "Khuyết tật vùng bề mặt"}]'::jsonb, 23);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 24, '一般的に、空気圧の応答速度は、油圧に比べて遅い。', 'Thông thường, tốc độ đáp ứng của khí nén chậm hơn thủy lực.', TRUE, 'Theo cách so sánh cơ bản của câu này, đáp án chính thức là đúng. Không khí nén được nên sự thay đổi áp suất và thể tích có thể gây độ trễ đáp ứng; dầu có độ nén nhỏ hơn. “Tốc độ đáp ứng” không đồng nghĩa với tốc độ chạy tối đa của xi lanh; kết quả thực còn phụ thuộc van, đường ống và thiết kế hệ thống.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "空気圧", "reading": "くうきあつ", "meaning": "Khí nén"}, {"term": "応答速度", "reading": "おうとうそくど", "meaning": "Tốc độ đáp ứng"}, {"term": "油圧", "reading": "ゆあつ", "meaning": "Thủy lực dùng dầu"}, {"term": "比べ", "reading": "くらべ", "meaning": "So sánh; so với (dạng nối câu của 比べる)"}, {"term": "遅い", "reading": "おそい", "meaning": "Chậm"}]'::jsonb, 24);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 25, '油圧バルブのうち、流量調整弁には、リリーフ弁やアンロード弁などがある。', 'Trong các van thủy lực, van điều chỉnh lưu lượng gồm van tràn và van xả tải.', FALSE, 'リリーフ弁 và アンロード弁 thuộc nhóm van điều khiển áp suất, không phải nhóm điều chỉnh lưu lượng. Van lưu lượng dùng để điều chỉnh lượng chất lưu đi qua và qua đó ảnh hưởng tốc độ cơ cấu chấp hành. Đề xếp sai nhóm chức năng.', '[{"term": "油圧バルブ", "reading": "ゆあつバルブ", "meaning": "Van thủy lực"}, {"term": "のうち", "reading": "のうち", "meaning": "Trong số…"}, {"term": "流量調整弁", "reading": "りゅうりょうちょうせいべん", "meaning": "Van điều chỉnh lưu lượng"}, {"term": "リリーフ弁", "reading": "リリーフべん", "meaning": "Van tràn; van giới hạn áp suất"}, {"term": "アンロード弁", "reading": "アンロードべん", "meaning": "Van xả tải"}]'::jsonb, 25);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 26, '作動油において、温度による粘度の変化が大きいほど、粘度指数が高いといえる。', 'Đối với dầu thủy lực, độ nhớt thay đổi theo nhiệt độ càng lớn thì chỉ số độ nhớt càng cao.', FALSE, '粘度指数 — chỉ số độ nhớt càng cao thì độ nhớt càng ít thay đổi theo nhiệt độ. Thay đổi lớn tương ứng chỉ số thấp hơn, trái với đề. Giải thích chỉ số độ nhớt — ENEOS', '[{"term": "作動油", "reading": "さどうゆ", "meaning": "Dầu thủy lực"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "温度", "reading": "おんど", "meaning": "Nhiệt độ"}, {"term": "による", "reading": "による", "meaning": "Do; theo; dựa trên, tùy ngữ cảnh"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "変化", "reading": "へんか", "meaning": "Thay đổi; biến thiên"}, {"term": "大きい", "reading": "おおきい", "meaning": "Lớn"}, {"term": "ほど", "reading": "ほど", "meaning": "Càng…; mức độ…"}, {"term": "粘度指数", "reading": "ねんどしすう", "meaning": "Chỉ số độ nhớt"}, {"term": "高い", "reading": "たかい", "meaning": "Cao"}, {"term": "といえる", "reading": "といえる", "meaning": "Có thể nói rằng…"}]'::jsonb, 26);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 27, 'セラミックスとは、石油や天然ガスから作られる合成樹脂のことである。', 'Gốm kỹ thuật là nhựa tổng hợp làm từ dầu mỏ hoặc khí thiên nhiên.', FALSE, 'Mô tả nguyên liệu và nhựa tổng hợp phù hợp với プラスチック, không phải セラミックス. Gốm là nhóm vật liệu vô cơ, phi kim loại. Đề đánh tráo hai nhóm vật liệu.', '[{"term": "セラミックス", "reading": "セラミックス", "meaning": "Gốm; vật liệu gốm kỹ thuật"}, {"term": "石油", "reading": "せきゆ", "meaning": "Dầu mỏ"}, {"term": "天然ガス", "reading": "てんねんガス", "meaning": "Khí thiên nhiên"}, {"term": "合成樹脂", "reading": "ごうせいじゅし", "meaning": "Nhựa tổng hợp"}]'::jsonb, 27);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 28, '電気めっきとは、絶縁材料を導電材料に変質させるための電気処理である。', 'Mạ điện là xử lý điện làm biến chất vật liệu cách điện thành vật liệu dẫn điện.', FALSE, '電気めっき tạo lớp kim loại phủ trên bề mặt bằng quá trình điện hóa. Mục tiêu có thể là chống ăn mòn, cải thiện bề mặt hoặc trang trí; không phải định nghĩa biến toàn bộ vật liệu cách điện thành vật liệu dẫn điện. Câu sai ở mô tả bản chất quá trình.', '[{"term": "電気めっき", "reading": "でんきめっき", "meaning": "Mạ điện"}, {"term": "絶縁材料", "reading": "ぜつえんざいりょう", "meaning": "Vật liệu cách điện"}, {"term": "導電材料", "reading": "どうでんざいりょう", "meaning": "Vật liệu dẫn điện"}, {"term": "変質", "reading": "へんしつ", "meaning": "Biến đổi tính chất"}, {"term": "電気処理", "reading": "でんきしょり", "meaning": "Xử lý bằng điện"}]'::jsonb, 28);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 29, 'ばねが自然長から伸び縮みする長さは、弾性力の大きさに比例する。', 'Độ giãn hoặc co của lò xo so với chiều dài tự nhiên tỷ lệ với độ lớn lực đàn hồi.', TRUE, 'Trong miền đàn hồi tuyến tính, định luật Hooke cho F = kx, nên x tỷ lệ với F khi độ cứng lò xo k không đổi. Điều này không áp dụng vượt giới hạn đàn hồi hoặc cho mọi lò xo phi tuyến. Đề dùng mô hình lò xo cơ bản nên được chấm đúng.', '[{"term": "ばね", "reading": "ばね", "meaning": "Lò xo"}, {"term": "自然長", "reading": "しぜんちょう", "meaning": "Chiều dài tự nhiên của lò xo"}, {"term": "伸び縮み", "reading": "のびちぢみ", "meaning": "Giãn và co"}, {"term": "長さ", "reading": "ながさ", "meaning": "Chiều dài"}, {"term": "弾性力", "reading": "だんせいりょく", "meaning": "Lực đàn hồi"}, {"term": "大きさ", "reading": "おおきさ", "meaning": "Độ lớn"}, {"term": "比例", "reading": "ひれい", "meaning": "Tỷ lệ thuận"}]'::jsonb, 29);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 30, 'すきまばめとは、穴の最小許容寸法より軸の最大許容寸法の方が小さいはめあいのことであ る。', 'Lắp lỏng là lắp ghép có kích thước lớn nhất cho phép của trục nhỏ hơn kích thước nhỏ nhất cho phép của lỗ.', TRUE, 'Điều kiện này bảo đảm ngay cả trục lớn nhất và lỗ nhỏ nhất vẫn có khe hở. Vì vậy đây là すきまばめ — lắp lỏng. Có thể biểu diễn điều kiện đề nêu bằng dmax < Dmin.', '[{"term": "すきまばめ", "reading": "すきまばめ", "meaning": "Lắp lỏng"}, {"term": "穴", "reading": "あな", "meaning": "Lỗ"}, {"term": "最小許容寸法", "reading": "さいしょうきょようすんぽう", "meaning": "Kích thước nhỏ nhất cho phép"}, {"term": "より", "reading": "より", "meaning": "So với; hơn (dùng khi so sánh)"}, {"term": "軸", "reading": "じく", "meaning": "Trục"}, {"term": "最大許容寸法", "reading": "さいだいきょようすんぽう", "meaning": "Kích thước lớn nhất cho phép"}, {"term": "小さい", "reading": "ちいさい", "meaning": "Nhỏ"}, {"term": "はめあい", "reading": "はめあい", "meaning": "Lắp ghép giữa lỗ và trục"}, {"term": "Bảng", "reading": "đáp", "meaning": "án nhanh — 2024 第1回"}, {"term": "Câu", "reading": "Đáp", "meaning": "án Câu Đáp án Câu Đáp án"}, {"term": "1", "reading": "○", "meaning": "11 × 21 ×"}, {"term": "2", "reading": "×", "meaning": "12 × 22 ○"}, {"term": "3", "reading": "×", "meaning": "13 ○ 23 ○"}, {"term": "4", "reading": "○", "meaning": "14 ○ 24 ○"}, {"term": "5", "reading": "○", "meaning": "15 ○ 25 ×"}, {"term": "6", "reading": "○", "meaning": "16 ○ 26 ×"}, {"term": "7", "reading": "×", "meaning": "17 × 27 ×"}, {"term": "8", "reading": "○", "meaning": "18 ○ 28 ×"}, {"term": "9", "reading": "×", "meaning": "19 × 29 ○"}, {"term": "10", "reading": "×", "meaning": "20 ○ 30 ○"}, {"term": "PHẦN", "reading": "2", "meaning": "— ĐỀ NĂM 2024 · 第2回"}, {"term": "Kỳ", "reading": "thi:", "meaning": "第2回・機械系保全作業・3級 学科試験. Ngày thi: 12/01/2025."}]'::jsonb, 30);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 1, '下図に示す工作機械は、ボール盤である。', 'Máy công cụ trong hình dưới là máy khoan.', FALSE, 'Hình là 旋盤 — máy tiện, có băng máy nằm ngang, bàn dao và ụ động. ボール盤 là máy khoan, có cấu tạo khác. Vì vậy nhận định trong đề sai.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}, {"term": "ボール盤", "reading": "ボールばん", "meaning": "Máy khoan"}]'::jsonb, 31);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 2, 'フライス盤とは、平面削りや溝削りなどの加工を行う工作機械である。', 'Máy phay là máy công cụ gia công mặt phẳng, rãnh và những dạng tương tự.', TRUE, 'フライス盤 sử dụng dao phay quay để gia công. Gia công mặt phẳng và rãnh là những ứng dụng điển hình. Nhận định đúng.', '[{"term": "フライス盤", "reading": "フライスばん", "meaning": "Máy phay"}, {"term": "平面削り", "reading": "へいめんけずり", "meaning": "Gia công/cắt mặt phẳng"}, {"term": "溝削り", "reading": "みぞけずり", "meaning": "Gia công/cắt rãnh"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}]'::jsonb, 32);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 3, '下図に示す回路の電圧Vは、1.5Vである。', 'Điện áp V của mạch dưới là 1,5 V.', FALSE, 'Hai điện trở 20 Ω và 10 Ω mắc nối tiếp nên Rt = 30 Ω. Dòng điện là 0,5 A, do đó V = IRt = 0,5 × 30 = 15 V. Đề ghi 1,5 V nên sai.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "回路", "reading": "かいろ", "meaning": "Mạch điện; mạch hệ thống, tùy ngữ cảnh"}, {"term": "電圧", "reading": "でんあつ", "meaning": "Điện áp"}]'::jsonb, 33);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 4, '2極と4極の三相誘導電動機を同じ電源で使用する場合、4極の回転数は2極の回転数の2倍に なる。', 'Khi động cơ không đồng bộ ba pha 2 cực và 4 cực dùng cùng nguồn, tốc độ của động cơ 4 cực gấp hai lần động cơ 2 cực.', FALSE, 'Tốc độ đồng bộ ns = 120f/p. Cùng tần số, tăng số cực từ 2 lên 4 làm tốc độ đồng bộ còn một nửa, không phải gấp đôi. Tốc độ rôto thực còn phụ thuộc độ trượt.', '[{"term": "極", "reading": "きょく", "meaning": "Cực của động cơ điện"}, {"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "Động cơ không đồng bộ ba pha"}, {"term": "同じ", "reading": "おなじ", "meaning": "Giống nhau; cùng"}, {"term": "電源", "reading": "でんげん", "meaning": "Nguồn điện"}, {"term": "使用", "reading": "しよう", "meaning": "Sử dụng"}, {"term": "場合", "reading": "ばあい", "meaning": "Trường hợp"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "Số vòng quay; trong câu này là tốc độ quay"}, {"term": "倍", "reading": "ばい", "meaning": "Lần; bội số"}, {"term": "になる", "reading": "になる", "meaning": "Trở thành; thay đổi thành"}]'::jsonb, 34);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 5, '生産保全とは、設備が故障したり機能が低下してから行う保全である。', 'Bảo trì sản xuất là bảo trì thực hiện sau khi thiết bị hỏng hoặc suy giảm chức năng.', FALSE, 'Mô tả này là 事後保全 — bảo trì sau hỏng. 生産保全 là cách tổ chức bảo trì hướng tới hiệu quả sản xuất và hiệu quả kinh tế của thiết bị, có thể kết hợp nhiều phương thức bảo trì. Không đồng nhất nó với chỉ sửa sau khi hỏng.', '[{"term": "生産保全", "reading": "せいさんほぜん", "meaning": "Bảo trì hướng tới hiệu quả sản xuất;"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "機能", "reading": "きのう", "meaning": "Chức năng"}, {"term": "低下", "reading": "ていか", "meaning": "Suy giảm"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "保全", "reading": "ほぜん", "meaning": "Bảo trì"}]'::jsonb, 35);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 6, '保全性の良い設備の例として、清掃、点検、給油などの定期整備が容易な設備が挙げられる。', 'Một ví dụ về thiết bị có khả năng bảo trì tốt là thiết bị dễ thực hiện bảo dưỡng định kỳ như vệ sinh, kiểm tra và cấp dầu.', TRUE, '保全性 biểu thị mức độ thuận lợi khi bảo trì, kiểm tra hoặc khôi phục thiết bị. Thiết kế dễ tiếp cận vị trí kiểm tra và cấp dầu giúp bảo trì dễ thực hiện hơn. Không nhầm 保全性 với việc thiết bị tuyệt đối không hỏng.', '[{"term": "保全性", "reading": "ほぜんせい", "meaning": "Khả năng/mức độ thuận lợi khi bảo trì"}, {"term": "良い", "reading": "よい", "meaning": "Tốt"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "例", "reading": "れい", "meaning": "Ví dụ"}, {"term": "清掃", "reading": "せいそう", "meaning": "Vệ sinh; làm sạch"}, {"term": "点検", "reading": "てんけん", "meaning": "Kiểm tra tình trạng"}, {"term": "給油", "reading": "きゅうゆ", "meaning": "Cấp dầu; tra dầu"}, {"term": "定期整備", "reading": "ていきせいび", "meaning": "Bảo dưỡng định kỳ"}, {"term": "容易", "reading": "ようい", "meaning": "Dễ dàng"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 36);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 7, '予知保全とは、過去の故障実績などを参考にし、一定の周期で点検や検査を行う保全である。', 'Bảo trì dự đoán là bảo trì thực hiện kiểm tra theo chu kỳ cố định dựa vào lịch sử hỏng.', FALSE, 'Chu kỳ cố định dựa trên lịch sử là cách lập bảo trì theo thời gian/định kỳ. 予知保全 dùng dữ liệu tình trạng như rung, nhiệt độ hoặc phân tích dầu để dự đoán diễn biến và nhu cầu bảo trì. Chỗ sai cần nhớ là 一定の周期 — chu kỳ cố định.', '[{"term": "予知保全", "reading": "よちほぜん", "meaning": "Bảo trì dự đoán"}, {"term": "過去", "reading": "かこ", "meaning": "Quá khứ"}, {"term": "故障実績", "reading": "こしょうじっせき", "meaning": "Dữ liệu/lịch sử hỏng thực tế"}, {"term": "参考", "reading": "さんこう", "meaning": "Tham khảo"}, {"term": "一定", "reading": "いってい", "meaning": "Cố định; nhất định"}, {"term": "周期", "reading": "しゅうき", "meaning": "Chu kỳ"}, {"term": "点検", "reading": "てんけん", "meaning": "Kiểm tra tình trạng"}, {"term": "検査", "reading": "けんさ", "meaning": "Kiểm tra; kiểm nghiệm"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "保全", "reading": "ほぜん", "meaning": "Bảo trì"}]'::jsonb, 37);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 8, '設備履歴簿には、設備の故障の内容や、修理に要した費用などの記録を残す。', 'Sổ lịch sử thiết bị ghi nội dung hỏng và các thông tin như chi phí cần cho sửa chữa.', TRUE, 'Hồ sơ này lưu thông tin về sự cố và sửa chữa để theo dõi thiết bị. Nội dung hỏng, biện pháp sửa và chi phí là các thông tin hữu ích cho lập kế hoạch bảo trì. Câu đúng.', '[{"term": "設備履歴簿", "reading": "せつびりれきぼ", "meaning": "Sổ lịch sử thiết bị"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "内容", "reading": "ないよう", "meaning": "Nội dung"}, {"term": "修理", "reading": "しゅうり", "meaning": "Sửa chữa"}, {"term": "要した", "reading": "ようした", "meaning": "Đã cần/đã tốn (dạng của 要する)"}, {"term": "費用", "reading": "ひよう", "meaning": "Chi phí"}, {"term": "記録", "reading": "きろく", "meaning": "Ghi chép; bản ghi"}, {"term": "残す", "reading": "のこす", "meaning": "Lưu lại; để lại"}]'::jsonb, 38);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 9, '下図に示すグラフは、散布図である。', 'Đồ thị trong hình dưới là biểu đồ phân tán.', FALSE, 'Hình là ヒストグラム — biểu đồ phân bố tần số, có các cột liền nhau thể hiện phân bố dữ liệu. 散布図 là biểu đồ phân tán, thường biểu diễn các cặp giá trị bằng các điểm. Đề gọi sai loại biểu đồ.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "グラフ", "reading": "グラフ", "meaning": "Đồ thị; biểu đồ"}, {"term": "散布図", "reading": "さんぷず", "meaning": "Biểu đồ phân tán"}]'::jsonb, 39);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 10, '作業標準書とは、誰がやっても同じ結果が出るように、人の動作・機械操作の手順を定めた ものである。', 'Bản tiêu chuẩn thao tác quy định trình tự động tác của người và vận hành máy để ai làm cũng có kết quả giống nhau.', TRUE, '作業標準書 chuẩn hóa cách làm và điều kiện thực hiện để kết quả nhất quán. Nó là tài liệu hướng dẫn chuẩn, khác với bản ghi thời gian sau mỗi lần làm. Đề mô tả đúng mục tiêu cơ bản của tiêu chuẩn thao tác.', '[{"term": "作業標準書", "reading": "さぎょうひょうじゅんしょ", "meaning": "Bản tiêu chuẩn/hướng dẫn thao tác"}, {"term": "誰", "reading": "だれ", "meaning": "Ai"}, {"term": "同じ", "reading": "おなじ", "meaning": "Giống nhau; cùng"}, {"term": "結果", "reading": "けっか", "meaning": "Kết quả"}, {"term": "出る", "reading": "でる", "meaning": "Xuất hiện; đạt được (kết quả)"}, {"term": "動作", "reading": "どうさ", "meaning": "Chuyển động; thao tác"}, {"term": "機械操作", "reading": "きかいそうさ", "meaning": "Vận hành máy"}, {"term": "手順", "reading": "てじゅん", "meaning": "Trình tự"}, {"term": "定めた", "reading": "さだめた", "meaning": "Đã quy định/đặt ra (dạng của 定める)"}]'::jsonb, 40);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 11, '炭素鋼材であるS20Cは、S10Cと比べ、炭素含有量が多い。', 'Thép cacbon S20C có hàm lượng cacbon lớn hơn S10C.', TRUE, 'Trong ký hiệu của hai mác thép này, số 20 và 10 biểu thị mức cacbon danh nghĩa tương ứng khoảng 0,20% và 0,10%. Vì vậy S20C có hàm lượng cacbon cao hơn S10C. Thành phần thực tế được quy định theo khoảng của mác thép.', '[{"term": "炭素鋼材", "reading": "たんそこうざい", "meaning": "Vật liệu thép cacbon"}, {"term": "S20C", "reading": "エスにじゅうシー", "meaning": "Ký hiệu mác thép cacbon S20C"}, {"term": "S10C", "reading": "エスじゅうシー", "meaning": "Ký hiệu mác thép cacbon S10C"}, {"term": "比べ", "reading": "くらべ", "meaning": "So sánh; so với (dạng nối câu của 比べる)"}, {"term": "炭素含有量", "reading": "たんそがんゆうりょう", "meaning": "Hàm lượng cacbon"}, {"term": "多い", "reading": "おおい", "meaning": "Nhiều"}]'::jsonb, 41);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 12, '合金鋼は、薄い金属の板を複数枚重ね合わせることで、耐荷重性を強化したものである。', 'Thép hợp kim được tạo bằng cách chồng nhiều tấm kim loại mỏng để tăng khả năng chịu tải.', FALSE, '合金鋼 là thép có bổ sung nguyên tố hợp kim để đạt tính chất mong muốn, chẳng hạn crôm, niken hoặc molypden tùy loại. Chồng nhiều tấm kim loại là cấu tạo ghép lớp, không phải định nghĩa thép hợp kim.', '[{"term": "合金鋼", "reading": "ごうきんこう", "meaning": "Thép hợp kim"}, {"term": "薄い", "reading": "うすい", "meaning": "Mỏng"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "板", "reading": "いた", "meaning": "Tấm; bản"}, {"term": "複数枚", "reading": "ふくすうまい", "meaning": "Nhiều tấm (枚 là từ đếm vật mỏng)"}, {"term": "重ね合わせる", "reading": "かさねあわせる", "meaning": "Chồng/lắp các lớp lên nhau"}, {"term": "耐荷重性", "reading": "たいかじゅうせい", "meaning": "Khả năng chịu tải"}, {"term": "強化", "reading": "きょうか", "meaning": "Tăng cường"}]'::jsonb, 42);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 13, '金属の熱処理は、加熱温度や冷却速度などを調節することにより、金属の性質を変えずに状 態変化させる。', 'Nhiệt luyện điều chỉnh nhiệt độ gia nhiệt, tốc độ làm nguội và các điều kiện khác để thay đổi trạng thái mà không thay đổi tính chất kim loại.', FALSE, 'Nhiệt luyện nhằm thay đổi hoặc cải thiện tính chất và tổ chức vật liệu. Cụm 金属の性質を変えずに — không thay đổi tính chất kim loại khiến mệnh đề sai. Ví dụ tôi có thể làm tăng độ cứng khi dùng vật liệu và chế độ phù hợp.', '[{"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "熱処理", "reading": "ねつしょり", "meaning": "Nhiệt luyện"}, {"term": "加熱温度", "reading": "かねつおんど", "meaning": "Nhiệt độ gia nhiệt"}, {"term": "冷却速度", "reading": "れいきゃくそくど", "meaning": "Tốc độ làm nguội"}, {"term": "調節", "reading": "ちょうせつ", "meaning": "Điều chỉnh"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "性質", "reading": "せいしつ", "meaning": "Tính chất"}, {"term": "変えずに", "reading": "かえずに", "meaning": "Không thay đổi… mà…"}, {"term": "状態変化", "reading": "じょうたいへんか", "meaning": "Thay đổi trạng thái"}]'::jsonb, 43);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 14, '労働災害とは、労働者の就業に係る建設物や設備などにより、または作業行動その他の業務 に起因して、労働者が負傷し、疾病にかかり、または死亡することをいう。', 'Tai nạn lao động là việc người lao động bị thương, mắc bệnh hoặc tử vong do công trình, thiết bị gắn với công việc hoặc do hành động làm việc và nguyên nhân nghiệp vụ khác.', TRUE, 'Mệnh đề nêu đúng trọng tâm của 労働災害: hậu quả đối với người lao động có nguồn gốc từ công việc. Đây không chỉ là hỏng thiết bị hoặc thiên tai nói chung. Định nghĩa — Bộ Y tế, Lao động và Phúc lợi Nhật Bản', '[{"term": "労働災害", "reading": "ろうどうさいがい", "meaning": "Tai nạn, bệnh tật hoặc tử vong do lao động"}, {"term": "労働者", "reading": "ろうどうしゃ", "meaning": "Người lao động"}, {"term": "就業", "reading": "しゅうぎょう", "meaning": "Làm việc; thực hiện công việc"}, {"term": "係る", "reading": "かかる", "meaning": "Liên quan đến"}, {"term": "建設物", "reading": "けんせつぶつ", "meaning": "Công trình xây dựng"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "または", "reading": "または", "meaning": "Hoặc"}, {"term": "作業行動", "reading": "さぎょうこうどう", "meaning": "Hành động/thao tác làm việc"}, {"term": "その他", "reading": "そのた", "meaning": "Khác; ngoài ra"}, {"term": "業務", "reading": "ぎょうむ", "meaning": "Công việc; hoạt động nghiệp vụ"}, {"term": "起因", "reading": "きいん", "meaning": "Bắt nguồn từ; do nguyên nhân"}, {"term": "負傷", "reading": "ふしょう", "meaning": "Bị thương"}, {"term": "疾病", "reading": "しっぺい", "meaning": "Bệnh tật"}, {"term": "かかり", "reading": "かかり", "meaning": "Mắc (bệnh); dạng nối câu của かかる"}, {"term": "死亡", "reading": "しぼう", "meaning": "Tử vong"}]'::jsonb, 44);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 15, '5Sにおける整頓とは、必要なものがすぐに取り出せるように、置き場所、置き方を決め、表 示を確実に行うことである。', 'Trong 5S, sắp xếp là xác định vị trí, cách đặt và đánh dấu rõ ràng để có thể lấy ngay thứ cần thiết.', TRUE, 'Đây là 整頓 — sắp xếp. Trọng tâm là dễ tìm, lấy và trả lại thứ cần thiết. Phân biệt với 整理 — phân loại và bỏ thứ không cần.', '[{"term": "5S", "reading": "ごエス", "meaning": "5S: sàng lọc, sắp xếp, sạch sẽ, duy trì sạch"}, {"term": "sẽ,", "reading": "rèn", "meaning": "nề nếp"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "整頓", "reading": "せいとん", "meaning": "Sắp xếp thứ cần thiết để dễ tìm, lấy và trả"}, {"term": "必要", "reading": "ひつよう", "meaning": "Cần thiết"}, {"term": "すぐに", "reading": "すぐに", "meaning": "Ngay; lập tức"}, {"term": "取り出せる", "reading": "とりだせる", "meaning": "Có thể lấy ra"}, {"term": "置き場所", "reading": "おきばしょ", "meaning": "Vị trí để/đặt"}, {"term": "置き方", "reading": "おきかた", "meaning": "Cách đặt"}, {"term": "決め", "reading": "きめ", "meaning": "Quyết định (dạng nối câu của 決める)"}, {"term": "表示", "reading": "ひょうじ", "meaning": "Hiển thị; ghi dấu/nhãn"}, {"term": "確実", "reading": "かくじつ", "meaning": "Chắc chắn; đầy đủ đáng tin cậy"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}]'::jsonb, 45);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 16, 'ねじの有効径とは、ねじ山とねじ溝の幅が等しくなるような仮想的な円筒の直径のことであ る。', 'Đường kính trung bình của ren là đường kính hình trụ tưởng tượng tại đó bề rộng gờ ren và rãnh ren bằng nhau.', TRUE, '有効径 là đường kính trung bình/đường kính hiệu dụng của ren theo định nghĩa hình học cơ bản này. Nó khác với đường kính ngoài và đường kính chân ren. Mệnh đề đúng.', '[{"term": "ねじ", "reading": "ねじ", "meaning": "Ren; vít, tùy ngữ cảnh"}, {"term": "有効径", "reading": "ゆうこうけい", "meaning": "Đường kính trung bình/hiệu dụng của ren"}, {"term": "ねじ山", "reading": "ねじやま", "meaning": "Gờ ren; phần nhô của ren"}, {"term": "ねじ溝", "reading": "ねじみぞ", "meaning": "Rãnh ren"}, {"term": "幅", "reading": "はば", "meaning": "Bề rộng"}, {"term": "等しく", "reading": "ひとしく", "meaning": "Bằng nhau (dạng của 等しい)"}, {"term": "仮想的", "reading": "かそうてき", "meaning": "Tưởng tượng; giả định"}, {"term": "円筒", "reading": "えんとう", "meaning": "Hình trụ"}, {"term": "直径", "reading": "ちょっけい", "meaning": "Đường kính"}]'::jsonb, 46);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 17, 'カムは、運動の方向を変える機械要素である。', 'Cam là chi tiết máy làm thay đổi hướng chuyển động.', TRUE, 'カム cùng cơ cấu theo cam dùng biến đổi chuyển động, chẳng hạn từ quay sang chuyển động tịnh tiến hoặc dao động theo biên dạng cam. Trong phạm vi mô tả cơ bản của đề, thay đổi hướng chuyển động là một công dụng phù hợp. Câu đúng.', '[{"term": "カム", "reading": "カム", "meaning": "Cam"}, {"term": "運動", "reading": "うんどう", "meaning": "Chuyển động"}, {"term": "方向", "reading": "ほうこう", "meaning": "Phương; hướng"}, {"term": "変える", "reading": "かえる", "meaning": "Thay đổi"}, {"term": "機械要素", "reading": "きかいようそ", "meaning": "Chi tiết/cơ cấu cơ bản của máy"}]'::jsonb, 47);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 18, 'シリンダゲージは、液体内につくられた気泡の位置がいつも高いことを利用した、角度の測 定器具である。', 'Đồng hồ đo lỗ là dụng cụ đo góc dựa trên tính chất bọt khí trong chất lỏng luôn ở vị trí cao.', FALSE, 'Đó là mô tả 水準器 — nivô, không phải シリンダゲージ. Đồng hồ đo lỗ dùng kiểm tra đường kính trong. Không nhầm dụng cụ đo lỗ với dụng cụ sử dụng bọt khí.', '[{"term": "シリンダゲージ", "reading": "シリンダゲージ", "meaning": "Đồng hồ đo lỗ"}, {"term": "液体", "reading": "えきたい", "meaning": "Chất lỏng"}, {"term": "気泡", "reading": "きほう", "meaning": "Bọt khí"}, {"term": "位置", "reading": "いち", "meaning": "Vị trí"}, {"term": "いつも", "reading": "いつも", "meaning": "Luôn luôn"}, {"term": "高い", "reading": "たかい", "meaning": "Cao"}, {"term": "利用", "reading": "りよう", "meaning": "Sử dụng; tận dụng"}, {"term": "角度", "reading": "かくど", "meaning": "Góc; độ nghiêng"}, {"term": "測定器具", "reading": "そくていきぐ", "meaning": "Dụng cụ đo"}]'::jsonb, 48);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 19, '軸受に発生する異常摩耗の原因の1つとして、電流が軸受を通過したことによるスパークが 挙げられる。', 'Một nguyên nhân gây mài mòn bất thường của ổ trục là tia lửa do dòng điện đi qua ổ trục.', FALSE, 'Tia lửa/phóng điện khi dòng điện đi qua ổ trục liên quan 電食 — hư hại do phóng điện, tạo nóng chảy cục bộ và các vết rỗ. Đề gán cơ chế này cho 異常摩耗 nên đáp án sai theo phân loại của câu hỏi. Phân biệt cơ chế điện thực — NTN', '[{"term": "軸受", "reading": "じくうけ", "meaning": "Ổ trục; ổ đỡ"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "異常摩耗", "reading": "いじょうまもう", "meaning": "Mài mòn bất thường"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "電流", "reading": "でんりゅう", "meaning": "Dòng điện"}, {"term": "通過", "reading": "つうか", "meaning": "Đi qua"}, {"term": "による", "reading": "による", "meaning": "Do; theo; dựa trên, tùy ngữ cảnh"}, {"term": "スパーク", "reading": "スパーク", "meaning": "Tia lửa/phóng điện"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 49);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 20, '潤滑油の粘度が低いほど、油膜が切れにくくなる。', 'Độ nhớt dầu bôi trơn càng thấp thì màng dầu càng khó bị đứt.', FALSE, 'Độ nhớt quá thấp so với điều kiện làm việc có thể khiến màng dầu không đủ để ngăn cách bề mặt. Vì vậy không thể kết luận “càng thấp càng khó đứt màng”. Chọn độ nhớt phù hợp với tải, tốc độ, nhiệt độ và yêu cầu thiết bị.', '[{"term": "潤滑油", "reading": "じゅんかつゆ", "meaning": "Dầu bôi trơn"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "低い", "reading": "ひくい", "meaning": "Thấp"}, {"term": "ほど", "reading": "ほど", "meaning": "Càng…; mức độ…"}, {"term": "油膜", "reading": "ゆまく", "meaning": "Màng dầu"}, {"term": "切れにくく", "reading": "きれにくく", "meaning": "Khó bị đứt hơn (dạng của 切れにくい)"}]'::jsonb, 50);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 21, 'スポット溶接とは、2つの母材の接合部分を燃焼ガスの炎で加熱して溶融することで、接合 する方法である。', 'Hàn điểm là phương pháp nối hai vật liệu cơ bản bằng ngọn lửa khí cháy làm nóng chảy phần nối.', FALSE, 'Hàn điểm thông dụng dùng điện trở sinh nhiệt và lực ép điện cực. Ngọn lửa khí cháy thuộc hàn khí. Chỗ sai là nhầm nguồn nhiệt của phương pháp.', '[{"term": "スポット溶接", "reading": "スポットようせつ", "meaning": "Hàn điểm"}, {"term": "母材", "reading": "ぼざい", "meaning": "Vật liệu cơ bản/vật liệu nền được nối"}, {"term": "接合部分", "reading": "せつごうぶぶん", "meaning": "Vị trí/phần nối"}, {"term": "燃焼ガス", "reading": "ねんしょうガス", "meaning": "Khí cháy"}, {"term": "炎", "reading": "ほのお", "meaning": "Ngọn lửa"}, {"term": "加熱", "reading": "かねつ", "meaning": "Gia nhiệt"}, {"term": "溶融", "reading": "ようゆう", "meaning": "Nóng chảy"}, {"term": "接合", "reading": "せつごう", "meaning": "Nối; ghép"}, {"term": "方法", "reading": "ほうほう", "meaning": "Phương pháp"}]'::jsonb, 51);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 22, 'ダイスは、おねじの加工に用いる切削工具である。', 'Bàn ren là dụng cụ cắt dùng gia công ren ngoài.', TRUE, 'ダイス dùng tạo ren ngoài; タップ dùng tạo ren trong. Câu nói đúng công dụng của bàn ren.', '[{"term": "ダイス", "reading": "ダイス", "meaning": "Bàn ren; trong câu này dùng gia công ren"}, {"term": "おねじ", "reading": "おねじ", "meaning": "Ren ngoài"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "用いる", "reading": "もちいる", "meaning": "Dùng; sử dụng"}, {"term": "切削工具", "reading": "せっさくこうぐ", "meaning": "Dụng cụ cắt"}]'::jsonb, 52);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 23, '非破壊検査は、検査部位を切断して観察した後、溶接などにより元の状態に復旧する検査方 法である。', 'Kiểm tra không phá hủy là cắt vị trí cần kiểm tra để quan sát, sau đó hàn hoặc làm cách khác để khôi phục trạng thái ban đầu.', FALSE, 'Cắt đối tượng để quan sát là kiểm tra có phá hủy; việc hàn lại sau đó không làm nó trở thành kiểm tra không phá hủy. 非破壊検査 sử dụng phương pháp thích hợp để khảo sát mà không phá hủy đối tượng theo cách đề mô tả. Câu sai ở 切断 — cắt đứt.', '[{"term": "非破壊検査", "reading": "ひはかいけんさ", "meaning": "Kiểm tra không phá hủy"}, {"term": "検査部位", "reading": "けんさぶい", "meaning": "Vị trí/bộ phận cần kiểm tra"}, {"term": "切断", "reading": "せつだん", "meaning": "Cắt đứt"}, {"term": "観察", "reading": "かんさつ", "meaning": "Quan sát"}, {"term": "溶接", "reading": "ようせつ", "meaning": "Hàn"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "元", "reading": "もと", "meaning": "Ban đầu; nguyên trạng"}, {"term": "状態", "reading": "じょうたい", "meaning": "Trạng thái"}, {"term": "復旧", "reading": "ふっきゅう", "meaning": "Khôi phục"}, {"term": "検査方法", "reading": "けんさほうほう", "meaning": "Phương pháp kiểm tra"}]'::jsonb, 53);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 24, '一般的に、油圧は空気圧と比べ、小型で大きな出力を得ることができる。', 'Thông thường, thủy lực có thể tạo đầu ra lớn với thiết bị nhỏ gọn hơn khí nén.', TRUE, 'Thủy lực thông dụng có thể làm việc ở áp suất cao hơn khí nén. Với xi lanh, lực lý tưởng F = pA; cùng diện tích pít tông, áp suất lớn hơn cho lực lớn hơn. Nhận định so sánh cơ bản của đề đúng.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "油圧", "reading": "ゆあつ", "meaning": "Thủy lực dùng dầu"}, {"term": "空気圧", "reading": "くうきあつ", "meaning": "Khí nén"}, {"term": "比べ", "reading": "くらべ", "meaning": "So sánh; so với (dạng nối câu của 比べる)"}, {"term": "小型", "reading": "こがた", "meaning": "Kích thước nhỏ; nhỏ gọn"}, {"term": "大きな", "reading": "おおきな", "meaning": "Lớn (dùng trước danh từ)"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "Đầu ra; công suất/lực đầu ra theo ngữ cảnh"}, {"term": "得る", "reading": "える", "meaning": "Thu được; đạt được"}, {"term": "ことができる", "reading": "ことができる", "meaning": "Có thể…"}]'::jsonb, 54);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 25, '油圧バルブのうち、圧力制御弁には、リリーフ弁やアンロード弁などがある。', 'Trong các van thủy lực, van điều khiển áp suất gồm van tràn và van xả tải.', TRUE, 'リリーフ弁 giới hạn áp suất; アンロード弁 xả tải theo điều kiện thiết kế mạch. Theo phân loại chức năng của đề, cả hai thuộc nhóm điều khiển áp suất. Không xếp chúng vào nhóm điều chỉnh lưu lượng hoặc điều khiển hướng.', '[{"term": "油圧バルブ", "reading": "ゆあつバルブ", "meaning": "Van thủy lực"}, {"term": "のうち", "reading": "のうち", "meaning": "Trong số…"}, {"term": "圧力制御弁", "reading": "あつりょくせいぎょべん", "meaning": "Van điều khiển áp suất"}, {"term": "リリーフ弁", "reading": "リリーフべん", "meaning": "Van tràn; van giới hạn áp suất"}, {"term": "アンロード弁", "reading": "アンロードべん", "meaning": "Van xả tải"}]'::jsonb, 55);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 26, '作動油が白濁する原因として、水分の混入が考えられる。', 'Nước lẫn vào dầu thủy lực là một nguyên nhân có thể khiến dầu đục trắng.', TRUE, 'Nước hòa lẫn/nhũ hóa trong dầu có thể tạo biểu hiện đục trắng. Đây là một dấu hiệu cần kiểm tra, không phải kết luận rằng mọi trường hợp dầu đục đều chỉ do nước. Mệnh đề “có thể là một nguyên nhân” là đúng.', '[{"term": "作動油", "reading": "さどうゆ", "meaning": "Dầu thủy lực"}, {"term": "白濁", "reading": "はくだく", "meaning": "Đục trắng"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "水分", "reading": "すいぶん", "meaning": "Nước; độ ẩm"}, {"term": "混入", "reading": "こんにゅう", "meaning": "Lẫn vào"}, {"term": "考えられる", "reading": "かんがえられる", "meaning": "Có thể nghĩ đến; có thể là"}]'::jsonb, 56);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 27, 'プラスチックとは、石油や天然ガスから作られる合成樹脂のことである。', 'Nhựa là nhựa tổng hợp được làm từ dầu mỏ hoặc khí thiên nhiên.', TRUE, 'Đây là mô tả cơ bản phù hợp với nhóm nhựa tổng hợp thông dụng từ nguyên liệu hóa dầu. Không nhầm プラスチック với セラミックス — vật liệu gốm vô cơ. Câu được chấm đúng trong phạm vi đề.', '[{"term": "プラスチック", "reading": "プラスチック", "meaning": "Nhựa"}, {"term": "石油", "reading": "せきゆ", "meaning": "Dầu mỏ"}, {"term": "天然ガス", "reading": "てんねんガス", "meaning": "Khí thiên nhiên"}, {"term": "合成樹脂", "reading": "ごうせいじゅし", "meaning": "Nhựa tổng hợp"}]'::jsonb, 57);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 28, 'ショットピーニングは、表面にクロム金属をめっきする表面硬化処理である。', 'Phun bi tăng bền là xử lý làm cứng bề mặt bằng cách mạ kim loại crôm lên bề mặt.', FALSE, 'ショットピーニング dùng các hạt cứng va đập lên bề mặt để gây biến dạng dẻo và thay đổi trạng thái bề mặt. Mạ crôm là quá trình phủ một lớp kim loại, khác với phun bi. Đề nhầm phương pháp xử lý bề mặt.', '[{"term": "ショットピーニング", "reading": "ショットピーニング", "meaning": "Phun bi tăng bền"}, {"term": "表面", "reading": "ひょうめん", "meaning": "Bề mặt"}, {"term": "クロム金属", "reading": "クロムきんぞく", "meaning": "Kim loại crôm"}, {"term": "めっき", "reading": "めっき", "meaning": "Mạ; lớp mạ"}, {"term": "表面硬化処理", "reading": "ひょうめんこうかしょり", "meaning": "Xử lý làm cứng bề mặt"}]'::jsonb, 58);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 29, 'ロープは、安全率が高くなるほど切れやすくなる。', 'Dây cáp/dây thừng càng có hệ số an toàn cao thì càng dễ đứt.', FALSE, 'Hệ số an toàn thường là tỷ số giữa khả năng chịu tải giới hạn và tải sử dụng cho phép. Với cùng khả năng chịu tải, chọn hệ số cao hơn nghĩa là dùng mức tải cho phép nhỏ hơn, không phải càng dễ đứt. Điều này không thay thế việc kiểm tra tình trạng dây.', '[{"term": "ロープ", "reading": "ロープ", "meaning": "Dây thừng/dây cáp tùy vật liệu và ngữ cảnh"}, {"term": "安全率", "reading": "あんぜんりつ", "meaning": "Hệ số an toàn"}, {"term": "ほど", "reading": "ほど", "meaning": "Càng…; mức độ…"}, {"term": "切れやすく", "reading": "きれやすく", "meaning": "Dễ bị đứt hơn (dạng của 切れやすい)"}]'::jsonb, 59);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第2回', 30, '下図に示す図面において、Aを寸法補助線という。', 'Trong bản vẽ dưới, A được gọi là đường gióng kích thước.', FALSE, 'A chỉ vào đường dẫn từ phần ghi φ11 đến đặc điểm cần chỉ: đó là 引出線 — đường dẫn chú thích/leader line. 寸法補助線 là đường gióng kích thước kéo từ vị trí cần đo đến đường kích thước. Đáp án sai vì gọi nhầm loại đường; φ11 chỉ đường kính 11 mm.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "図面", "reading": "ずめん", "meaning": "Bản vẽ"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "寸法補助線", "reading": "すんぽうほじょせん", "meaning": "Đường gióng kích thước"}, {"term": "という", "reading": "という", "meaning": "Gọi là; có tên là"}, {"term": "Bảng", "reading": "đáp", "meaning": "án nhanh — 2024 第2回"}, {"term": "Câu", "reading": "Đáp", "meaning": "án Câu Đáp án Câu Đáp án"}, {"term": "1", "reading": "×", "meaning": "11 ○ 21 ×"}, {"term": "2", "reading": "○", "meaning": "12 × 22 ○"}, {"term": "3", "reading": "×", "meaning": "13 × 23 ×"}, {"term": "4", "reading": "×", "meaning": "14 ○ 24 ○"}, {"term": "5", "reading": "×", "meaning": "15 ○ 25 ○"}, {"term": "6", "reading": "○", "meaning": "16 ○ 26 ○"}, {"term": "7", "reading": "×", "meaning": "17 ○ 27 ○"}, {"term": "8", "reading": "○", "meaning": "18 × 28 ×"}, {"term": "9", "reading": "×", "meaning": "19 × 29 ×"}, {"term": "10", "reading": "○", "meaning": "20 × 30 ×"}, {"term": "PHẦN", "reading": "3", "meaning": "— ĐỀ NĂM 2025"}, {"term": "Kỳ", "reading": "thi:", "meaning": "第1回・機械系保全作業・3級 学科試験. Ngày thi: 22/06/2025."}]'::jsonb, 60);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 1, '下図に示す工作機械は、旋盤である。', 'Máy công cụ trong hình dưới là máy tiện.', FALSE, 'Hình là máy khoan đứng ボール盤, không phải máy tiện 旋盤. Có thể nhận ra đầu khoan ở phía trên, cột đứng và bàn đặt phôi bên dưới. Với máy khoan, dao khoan quay; với máy tiện thông thường, phôi quay.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}, {"term": "旋盤", "reading": "せんばん", "meaning": "Máy tiện"}]'::jsonb, 61);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 2, 'フライス盤とは、工作物を主軸に取り付け、工作物を回転させながら加工を行う工作機械で ある。', 'Máy phay là máy công cụ gia công bằng cách gắn phôi vào trục chính và cho phôi quay.', FALSE, 'Mô tả này thuộc về máy tiện. Khi phay, dao phay gắn trên trục chính quay để cắt; phôi được gá và có chuyển động chạy dao tương đối với dao. Chỗ sai cần nhớ là 工作物を回転させる — cho phôi quay.', '[{"term": "フライス盤", "reading": "フライスばん", "meaning": "Máy phay"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "Phôi; vật gia công"}, {"term": "主軸", "reading": "しゅじく", "meaning": "Trục chính"}, {"term": "取り付け", "reading": "とりつけ", "meaning": "Lắp; gắn (dạng nối câu của 取り付ける)"}, {"term": "回転", "reading": "かいてん", "meaning": "Chuyển động quay"}, {"term": "させながら", "reading": "させながら", "meaning": "Vừa cho/làm cho… vừa…"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}]'::jsonb, 62);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 3, '下図に示す回路の合成抵抗は、50Ωである。', 'Điện trở tương đương của mạch trong hình dưới là 50 Ω.', TRUE, 'Hai điện trở 100 Ω mắc song song. 1/Rt = 1/100 + 1/100 = 2/100, nên Rt = 50 Ω. Hai điện trở bằng nhau mắc song song có điện trở tương đương bằng một nửa giá trị mỗi điện trở.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "回路", "reading": "かいろ", "meaning": "Mạch điện; mạch hệ thống, tùy ngữ cảnh"}, {"term": "合成抵抗", "reading": "ごうせいていこう", "meaning": "Điện trở tương đương"}, {"term": "Ω", "reading": "オーム", "meaning": "Ôm; đơn vị điện trở"}]'::jsonb, 63);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 4, '60Hzで使用している三相誘導電動機を50Hzで使用すると、回転数は6/5倍になる。', 'Khi dùng động cơ không đồng bộ ba pha đang chạy ở 60 Hz với nguồn 50 Hz, tốc độ quay trở thành 6/5 lần.', FALSE, 'Đề đảo ngược tỷ số. Với số cực không đổi, tốc độ đồng bộ ns = 120f/p; giảm tần số từ 60 xuống 50 Hz làm tỷ số tốc độ đồng bộ bằng 50/60 = 5/6. Tốc độ rôto thực còn phụ thuộc độ trượt, nhưng theo cách so sánh cơ bản của đề thì tốc độ giảm, không tăng lên 6/5. Công thức tốc độ đồng bộ — Oriental Motor', '[{"term": "Hz", "reading": "ヘルツ", "meaning": "Héc; đơn vị tần số"}, {"term": "使用", "reading": "しよう", "meaning": "Sử dụng"}, {"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "Động cơ không đồng bộ ba pha"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "Số vòng quay; trong câu này là tốc độ quay"}, {"term": "倍", "reading": "ばい", "meaning": "Lần; bội số"}, {"term": "になる", "reading": "になる", "meaning": "Trở thành; thay đổi thành"}]'::jsonb, 64);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 5, '事後保全は、予め定められた計画に沿って設備を停止して、分解・点検・整備をする保全方 式である。', 'Bảo trì sau khi hỏng là phương pháp dừng thiết bị theo kế hoạch định trước để tháo rời, kiểm tra và bảo dưỡng.', FALSE, '事後保全 là bảo trì sau khi hỏng hoặc mất chức năng đã xảy ra. Dừng máy theo kế hoạch để phòng ngừa hỏng là nội dung của bảo trì phòng ngừa theo lịch, không phải định nghĩa bảo trì sau hỏng. Chú ý từ 事後: sau sự việc.', '[{"term": "事後保全", "reading": "じごほぜん", "meaning": "Bảo trì sau khi hỏng"}, {"term": "予め", "reading": "あらかじめ", "meaning": "Trước; từ trước"}, {"term": "定められた", "reading": "さだめられた", "meaning": "Đã được quy định/định trước"}, {"term": "計画", "reading": "けいかく", "meaning": "Kế hoạch"}, {"term": "沿って", "reading": "そって", "meaning": "Theo; tuân theo"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "停止", "reading": "ていし", "meaning": "Dừng"}, {"term": "分解", "reading": "ぶんかい", "meaning": "Tháo rời; phân rã"}, {"term": "点検", "reading": "てんけん", "meaning": "Kiểm tra tình trạng"}, {"term": "整備", "reading": "せいび", "meaning": "Bảo dưỡng; chỉnh sửa để duy trì trạng thái"}, {"term": "保全方式", "reading": "ほぜんほうしき", "meaning": "Phương thức bảo trì"}]'::jsonb, 65);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 6, '保全性の良い設備の例として、清掃、点検、給油などの定期整備が容易な設備が挙げられる。', 'Một ví dụ về thiết bị có khả năng bảo trì tốt là thiết bị dễ thực hiện bảo dưỡng định kỳ như vệ sinh, kiểm tra và cấp dầu.', TRUE, '保全性 biểu thị mức độ thuận lợi khi bảo trì, kiểm tra hoặc khôi phục thiết bị. Thiết kế dễ tiếp cận vị trí kiểm tra và cấp dầu giúp bảo trì dễ thực hiện hơn. Không nhầm 保全性 với việc thiết bị tuyệt đối không hỏng.', '[{"term": "保全性", "reading": "ほぜんせい", "meaning": "Khả năng/mức độ thuận lợi khi bảo trì"}, {"term": "良い", "reading": "よい", "meaning": "Tốt"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "例", "reading": "れい", "meaning": "Ví dụ"}, {"term": "清掃", "reading": "せいそう", "meaning": "Vệ sinh; làm sạch"}, {"term": "点検", "reading": "てんけん", "meaning": "Kiểm tra tình trạng"}, {"term": "給油", "reading": "きゅうゆ", "meaning": "Cấp dầu; tra dầu"}, {"term": "定期整備", "reading": "ていきせいび", "meaning": "Bảo dưỡng định kỳ"}, {"term": "容易", "reading": "ようい", "meaning": "Dễ dàng"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 66);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 7, 'バスタブ曲線は、時間経過による機械や装置などの故障率の変化を表すグラフである。', 'Đường cong bồn tắm là đồ thị thể hiện sự thay đổi tỷ lệ hỏng của máy và thiết bị theo thời gian.', TRUE, 'バスタブ曲線 mô tả điển hình ba giai đoạn: hỏng ban đầu, hỏng ngẫu nhiên và hỏng do hao mòn. Trục ngang là thời gian, trục dọc là tỷ lệ hỏng. Tên gọi xuất phát từ hình dạng giống mặt cắt bồn tắm.', '[{"term": "バスタブ曲線", "reading": "バスタブきょくせん", "meaning": "Đường cong bồn tắm"}, {"term": "時間経過", "reading": "じかんけいか", "meaning": "Sự trôi qua của thời gian"}, {"term": "による", "reading": "による", "meaning": "Do; theo; dựa trên, tùy ngữ cảnh"}, {"term": "機械", "reading": "きかい", "meaning": "Máy; máy móc"}, {"term": "装置", "reading": "そうち", "meaning": "Thiết bị; cơ cấu"}, {"term": "故障率", "reading": "こしょうりつ", "meaning": "Tỷ lệ hỏng theo thời gian"}, {"term": "変化", "reading": "へんか", "meaning": "Thay đổi; biến thiên"}, {"term": "表す", "reading": "あらわす", "meaning": "Biểu diễn; thể hiện"}, {"term": "グラフ", "reading": "グラフ", "meaning": "Đồ thị; biểu đồ"}]'::jsonb, 67);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 8, '腐食とは、金属が他の固体と接触して発生する摩擦力により、表面が損傷したり、すり減る 現象である。', 'Ăn mòn là hiện tượng bề mặt kim loại bị hư hại hoặc hao mòn do lực ma sát sinh ra khi tiếp xúc với chất rắn khác.', FALSE, 'Nội dung mô tả 摩耗 — mài mòn, không phải 腐食 — ăn mòn. Ăn mòn liên quan đến tương tác hóa học hoặc điện hóa với môi trường; mài mòn liên quan đến tác động cơ học trên bề mặt. Ví dụ gỉ thép là ăn mòn.', '[{"term": "腐食", "reading": "ふしょく", "meaning": "Ăn mòn"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "固体", "reading": "こたい", "meaning": "Chất rắn; vật rắn"}, {"term": "接触", "reading": "せっしょく", "meaning": "Tiếp xúc"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "摩擦力", "reading": "まさつりょく", "meaning": "Lực ma sát"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "表面", "reading": "ひょうめん", "meaning": "Bề mặt"}, {"term": "損傷", "reading": "そんしょう", "meaning": "Hư hại; tổn thương"}, {"term": "すり減る", "reading": "すりへる", "meaning": "Mòn đi do cọ xát"}, {"term": "現象", "reading": "げんしょう", "meaning": "Hiện tượng"}]'::jsonb, 68);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 9, '下図に示すような品質管理の手法は、特性要因図である。', 'Phương pháp quản lý chất lượng trong hình dưới là biểu đồ nguyên nhân–kết quả.', TRUE, 'Hình có một trục chính hướng đến 結果 — kết quả, với các nhánh 人 — con người, 機械 — máy, 方法 — phương pháp và 材料 — vật liệu. Đây là 特性要因図, còn gọi là biểu đồ xương cá. Biểu đồ giúp tổ chức các nguyên nhân có thể có, không tự chứng minh nguyên nhân nào là đúng.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "品質管理", "reading": "ひんしつかんり", "meaning": "Quản lý chất lượng"}, {"term": "手法", "reading": "しゅほう", "meaning": "Phương pháp; cách tiếp cận"}, {"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "Biểu đồ nguyên nhân–kết quả; biểu đồ"}]'::jsonb, 69);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 10, '作業標準書とは、作業者が作業にかかった時間を、作業のたびに記入するものである。', 'Bản tiêu chuẩn thao tác là tài liệu để người lao động ghi thời gian thực hiện sau mỗi lần làm việc.', FALSE, '作業標準書 quy định phương pháp, trình tự, điều kiện và điểm cần chú ý để làm công việc nhất quán. Tài liệu ghi thời gian mỗi lần làm là bản ghi thực hiện/thời gian công việc. Chỗ sai là nhầm tài liệu hướng dẫn chuẩn với tài liệu ghi kết quả.', '[{"term": "作業標準書", "reading": "さぎょうひょうじゅんしょ", "meaning": "Bản tiêu chuẩn/hướng dẫn thao tác"}, {"term": "作業者", "reading": "さぎょうしゃ", "meaning": "Người thực hiện công việc"}, {"term": "作業", "reading": "さぎょう", "meaning": "Công việc; thao tác"}, {"term": "かかった時間", "reading": "かかったじかん", "meaning": "Thời gian đã mất/đã dùng"}, {"term": "たびに", "reading": "たびに", "meaning": "Mỗi khi; mỗi lần"}, {"term": "記入", "reading": "きにゅう", "meaning": "Điền; ghi vào"}]'::jsonb, 70);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 11, 'アルミニウムは、銅より熱伝導率が小さい。', 'Nhôm có độ dẫn nhiệt nhỏ hơn đồng.', TRUE, 'Trong so sánh thông thường giữa nhôm và đồng, đồng có độ dẫn nhiệt cao hơn. Trị số cụ thể thay đổi theo độ tinh khiết, thành phần và nhiệt độ. Vì vậy nhận định “nhôm nhỏ hơn đồng” là đúng.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "Nhôm"}, {"term": "銅", "reading": "どう", "meaning": "Đồng"}, {"term": "より", "reading": "より", "meaning": "So với; hơn (dùng khi so sánh)"}, {"term": "熱伝導率", "reading": "ねつでんどうりつ", "meaning": "Hệ số dẫn nhiệt"}, {"term": "小さい", "reading": "ちいさい", "meaning": "Nhỏ"}]'::jsonb, 71);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 12, '合金鋼は、薄い金属の板を複数枚重ね合わせることで、耐荷重性を強化したものである。', 'Thép hợp kim được tạo bằng cách chồng nhiều tấm kim loại mỏng để tăng khả năng chịu tải.', FALSE, '合金鋼 là thép có bổ sung nguyên tố hợp kim để đạt tính chất mong muốn, chẳng hạn crôm, niken hoặc molypden tùy loại. Chồng nhiều tấm kim loại là cấu tạo ghép lớp, không phải định nghĩa thép hợp kim.', '[{"term": "合金鋼", "reading": "ごうきんこう", "meaning": "Thép hợp kim"}, {"term": "薄い", "reading": "うすい", "meaning": "Mỏng"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "板", "reading": "いた", "meaning": "Tấm; bản"}, {"term": "複数枚", "reading": "ふくすうまい", "meaning": "Nhiều tấm (枚 là từ đếm vật mỏng)"}, {"term": "重ね合わせる", "reading": "かさねあわせる", "meaning": "Chồng/lắp các lớp lên nhau"}, {"term": "耐荷重性", "reading": "たいかじゅうせい", "meaning": "Khả năng chịu tải"}, {"term": "強化", "reading": "きょうか", "meaning": "Tăng cường"}]'::jsonb, 72);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 13, '鋼の焼なましは、鋼を軟化させ、加工しやすくする熱処理の方法である。', 'Ủ thép là phương pháp nhiệt luyện làm thép mềm hơn và dễ gia công hơn.', TRUE, '焼なまし — ủ được dùng để làm mềm và cải thiện khả năng gia công, đồng thời có thể giảm ứng suất hoặc điều chỉnh tổ chức tùy chế độ. Phân biệt với 焼入れ — tôi và 焼戻し — ram. Mệnh đề nêu một tác dụng cơ bản của ủ nên đúng.', '[{"term": "鋼", "reading": "はがね", "meaning": "Thép (khi đứng riêng trong câu)"}, {"term": "焼なまし", "reading": "やきなまし", "meaning": "Ủ (nhiệt luyện)"}, {"term": "軟化", "reading": "なんか", "meaning": "Làm mềm; mềm hóa"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "しやすくする", "reading": "しやすくする", "meaning": "Làm cho dễ… hơn"}, {"term": "熱処理", "reading": "ねつしょり", "meaning": "Nhiệt luyện"}, {"term": "方法", "reading": "ほうほう", "meaning": "Phương pháp"}]'::jsonb, 73);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 14, '労働災害とは、火災や地震など、設備の損傷原因となる災害のことである。', 'Tai nạn lao động là các thiên tai hoặc tai họa như hỏa hoạn, động đất gây hư hại thiết bị.', FALSE, '労働災害 nói đến người lao động bị thương, mắc bệnh hoặc tử vong do công việc. Hư hại thiết bị đơn thuần không đủ để gọi là tai nạn lao động theo nghĩa này. Trọng tâm cần nhớ là thiệt hại đối với người gắn với hoạt động lao động. Định nghĩa — Bộ Y tế, Lao động và Phúc lợi Nhật Bản', '[{"term": "労働災害", "reading": "ろうどうさいがい", "meaning": "Tai nạn, bệnh tật hoặc tử vong do lao động"}, {"term": "火災", "reading": "かさい", "meaning": "Hỏa hoạn"}, {"term": "地震", "reading": "じしん", "meaning": "Động đất"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "損傷", "reading": "そんしょう", "meaning": "Hư hại; tổn thương"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "災害", "reading": "さいがい", "meaning": "Tai họa; thảm họa"}]'::jsonb, 74);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 15, '5Sにおける整頓とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, “sắp xếp” là phân chia thứ cần thiết và không cần thiết rồi loại bỏ thứ không cần.', FALSE, 'Đó là 整理 — sàng lọc/phân loại, không phải 整頓 — sắp xếp. 整頓 là đặt những thứ cần thiết đúng vị trí để dễ tìm, lấy và trả lại. Hai chữ giống nhau về chủ đề nhưng khác mục tiêu.', '[{"term": "5S", "reading": "ごエス", "meaning": "5S: sàng lọc, sắp xếp, sạch sẽ, duy trì sạch"}, {"term": "sẽ,", "reading": "rèn", "meaning": "nề nếp"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "整頓", "reading": "せいとん", "meaning": "Sắp xếp thứ cần thiết để dễ tìm, lấy và trả"}, {"term": "必要", "reading": "ひつよう", "meaning": "Cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "Không cần thiết"}, {"term": "区分", "reading": "くぶん", "meaning": "Phân chia; phân loại"}, {"term": "なくす", "reading": "なくす", "meaning": "Loại bỏ; làm cho không còn"}]'::jsonb, 75);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 16, 'おねじとは、ねじ山が円筒または円錐の外側にあるねじである。', 'Ren ngoài là ren có đỉnh ren ở bên ngoài hình trụ hoặc hình côn.', TRUE, 'おねじ là ren ngoài; めねじ là ren trong. Ren trên thân bu lông là ví dụ dễ nhớ của おねじ. Đề mô tả đúng vị trí của ren ngoài.', '[{"term": "おねじ", "reading": "おねじ", "meaning": "Ren ngoài"}, {"term": "ねじ山", "reading": "ねじやま", "meaning": "Gờ ren; phần nhô của ren"}, {"term": "円筒", "reading": "えんとう", "meaning": "Hình trụ"}, {"term": "または", "reading": "または", "meaning": "Hoặc"}, {"term": "円錐", "reading": "えんすい", "meaning": "Hình nón; hình côn"}, {"term": "外側", "reading": "そとがわ", "meaning": "Phía ngoài"}, {"term": "ねじ", "reading": "ねじ", "meaning": "Ren; vít, tùy ngữ cảnh"}]'::jsonb, 76);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 17, '平歯車は、噛み合った2つの歯車の軸が直角に交わる歯車である。', 'Bánh răng trụ răng thẳng là loại có hai trục của hai bánh răng ăn khớp giao nhau vuông góc.', FALSE, '平歯車 truyền chuyển động giữa các trục song song. Hai trục giao nhau thường được dùng với かさ歯車 — bánh răng côn; góc giữa trục do thiết kế quyết định, thường gặp 90°. Chỗ sai trong đề là 直角に交わる — giao nhau vuông góc.', '[{"term": "平歯車", "reading": "ひらはぐるま", "meaning": "Bánh răng trụ răng thẳng"}, {"term": "噛み合った", "reading": "かみあった", "meaning": "Đã ăn khớp (dạng của 噛み合う)"}, {"term": "歯車", "reading": "はぐるま", "meaning": "Bánh răng"}, {"term": "軸", "reading": "じく", "meaning": "Trục"}, {"term": "直角", "reading": "ちょっかく", "meaning": "Góc vuông; vuông góc"}, {"term": "交わる", "reading": "まじわる", "meaning": "Giao nhau"}]'::jsonb, 77);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 18, 'シリンダゲージは、液体内につくられた気泡の位置がいつも高いことを利用した、角度の測 定器である。', 'Đồng hồ đo lỗ là dụng cụ đo góc dựa trên tính chất bọt khí trong chất lỏng luôn ở vị trí cao.', FALSE, 'Mô tả bọt khí thuộc 水準器 — nivô/thước thủy. シリンダゲージ là dụng cụ dùng đo đường kính trong của lỗ. Không nhầm tên シリンダゲージ với dụng cụ có ống chất lỏng.', '[{"term": "シリンダゲージ", "reading": "シリンダゲージ", "meaning": "Đồng hồ đo lỗ"}, {"term": "液体", "reading": "えきたい", "meaning": "Chất lỏng"}, {"term": "気泡", "reading": "きほう", "meaning": "Bọt khí"}, {"term": "位置", "reading": "いち", "meaning": "Vị trí"}, {"term": "いつも", "reading": "いつも", "meaning": "Luôn luôn"}, {"term": "高い", "reading": "たかい", "meaning": "Cao"}, {"term": "利用", "reading": "りよう", "meaning": "Sử dụng; tận dụng"}, {"term": "角度", "reading": "かくど", "meaning": "Góc; độ nghiêng"}, {"term": "測定器", "reading": "そくていき", "meaning": "Dụng cụ/thiết bị đo"}]'::jsonb, 78);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 19, 'すべり軸受に発生する焼付きの原因の1つとして、潤滑不足が挙げられる。', 'Một nguyên nhân gây bó kẹt ở ổ trượt là thiếu bôi trơn.', TRUE, 'Thiếu bôi trơn làm giảm khả năng ngăn cách bề mặt, tăng tiếp xúc, ma sát và nhiệt. Trong điều kiện nghiêm trọng có thể gây 焼付き — dính bề mặt/bó kẹt. Đây là một nguyên nhân; không phải nguyên nhân duy nhất.', '[{"term": "すべり軸受", "reading": "すべりじくうけ", "meaning": "Ổ trượt"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "焼付き", "reading": "やきつき", "meaning": "Bó kẹt/dính bề mặt do ma sát và nhiệt"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "潤滑不足", "reading": "じゅんかつぶそく", "meaning": "Thiếu bôi trơn"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 79);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 20, '一般的に、潤滑油の粘度は、温度が上昇すると減少する。', 'Thông thường, độ nhớt dầu bôi trơn giảm khi nhiệt độ tăng.', TRUE, 'Dầu thường đặc hơn khi lạnh và loãng hơn khi nóng. Do đó 温度が上昇 — nhiệt độ tăng đi cùng 粘度が減少 — độ nhớt giảm. Nhớ phân biệt độ nhớt ở một nhiệt độ với chỉ số độ nhớt, là mức độ nhạy với thay đổi nhiệt độ.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "潤滑油", "reading": "じゅんかつゆ", "meaning": "Dầu bôi trơn"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "温度", "reading": "おんど", "meaning": "Nhiệt độ"}, {"term": "上昇", "reading": "じょうしょう", "meaning": "Tăng lên"}, {"term": "減少", "reading": "げんしょう", "meaning": "Giảm"}]'::jsonb, 80);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 21, 'スポット溶接とは、2つの母材の接合部分をガスの炎で溶融することで、接合する方法であ る。', 'Hàn điểm là phương pháp nối hai vật liệu cơ bản bằng cách làm nóng chảy vị trí nối bằng ngọn lửa khí.', FALSE, 'スポット溶接 thông dụng là hàn điểm điện trở: dòng điện và lực ép điện cực tạo mối hàn tại điểm tiếp xúc. Gia nhiệt bằng ngọn lửa khí là đặc trưng của ガス溶接 — hàn khí. Phân loại hàn điện trở — TWI', '[{"term": "スポット溶接", "reading": "スポットようせつ", "meaning": "Hàn điểm"}, {"term": "母材", "reading": "ぼざい", "meaning": "Vật liệu cơ bản/vật liệu nền được nối"}, {"term": "接合部分", "reading": "せつごうぶぶん", "meaning": "Vị trí/phần nối"}, {"term": "ガス", "reading": "ガス", "meaning": "Khí"}, {"term": "炎", "reading": "ほのお", "meaning": "Ngọn lửa"}, {"term": "溶融", "reading": "ようゆう", "meaning": "Nóng chảy"}, {"term": "接合", "reading": "せつごう", "meaning": "Nối; ghép"}, {"term": "方法", "reading": "ほうほう", "meaning": "Phương pháp"}]'::jsonb, 81);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 22, 'ダイスは、おねじの加工に用いる工具である。', 'Bàn ren là dụng cụ dùng gia công ren ngoài.', TRUE, 'ダイス — bàn ren dùng tạo ren ngoài, ví dụ trên thanh tròn. タップ — tarô dùng tạo ren trong của lỗ. Cặp ダイス／タップ rất dễ xuất hiện trong bài phân biệt công dụng dụng cụ.', '[{"term": "ダイス", "reading": "ダイス", "meaning": "Bàn ren; trong câu này dùng gia công ren"}, {"term": "おねじ", "reading": "おねじ", "meaning": "Ren ngoài"}, {"term": "加工", "reading": "かこう", "meaning": "Gia công"}, {"term": "用いる", "reading": "もちいる", "meaning": "Dùng; sử dụng"}, {"term": "工具", "reading": "こうぐ", "meaning": "Dụng cụ"}]'::jsonb, 82);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 23, '非破壊検査には、放射線透過検査や磁粉探傷検査などがある。', 'Kiểm tra không phá hủy gồm kiểm tra chụp xuyên tia và kiểm tra từ tính bằng bột từ.', TRUE, '放射線透過検査 dùng bức xạ để khảo sát khuyết tật; 磁粉探傷検査 dùng từ hóa và bột từ để phát hiện khuyết tật phù hợp trên vật liệu sắt từ. Chúng được xếp vào 非破壊検査 vì không phải phá mẫu để kiểm tra. Không phải mọi phương pháp đều phù hợp với mọi vật liệu.', '[{"term": "非破壊検査", "reading": "ひはかいけんさ", "meaning": "Kiểm tra không phá hủy"}, {"term": "放射線透過検査", "reading": "ほうしゃせんとうかけんさ", "meaning": "Kiểm tra chụp xuyên tia/bức xạ"}, {"term": "磁粉探傷検査", "reading": "じふんたんしょうけんさ", "meaning": "Kiểm tra khuyết tật bằng bột từ"}]'::jsonb, 83);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 24, '一般的に、空気圧は油圧と比べ、小型で大きな出力を得ることができる。', 'Thông thường, khí nén có thể tạo công suất/lực đầu ra lớn bằng thiết bị nhỏ gọn hơn thủy lực.', FALSE, 'Nhìn chung thủy lực phù hợp hơn khi cần lực lớn với cơ cấu chấp hành nhỏ gọn, vì có thể làm việc ở áp suất cao hơn khí nén thông dụng. Với xi lanh, lực lý tưởng F = pA; cùng diện tích pít tông, áp suất lớn hơn cho lực lớn hơn. Đề đã đảo đặc điểm so sánh.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "空気圧", "reading": "くうきあつ", "meaning": "Khí nén"}, {"term": "油圧", "reading": "ゆあつ", "meaning": "Thủy lực dùng dầu"}, {"term": "比べ", "reading": "くらべ", "meaning": "So sánh; so với (dạng nối câu của 比べる)"}, {"term": "小型", "reading": "こがた", "meaning": "Kích thước nhỏ; nhỏ gọn"}, {"term": "大きな", "reading": "おおきな", "meaning": "Lớn (dùng trước danh từ)"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "Đầu ra; công suất/lực đầu ra theo ngữ cảnh"}, {"term": "得る", "reading": "える", "meaning": "Thu được; đạt được"}, {"term": "ことができる", "reading": "ことができる", "meaning": "Có thể…"}]'::jsonb, 84);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 25, '油圧バルブのうち、圧力制御弁には、チェック弁などがある。', 'Trong các van thủy lực, van điều khiển áp suất gồm van một chiều.', FALSE, 'チェック弁 — van một chiều cho phép chảy theo một chiều và chặn chiều ngược; trong phân loại chức năng của đề, nó thuộc nhóm điều khiển hướng. Ví dụ van áp suất là リリーフ弁 — van tràn và 減圧弁 — van giảm áp. Chỗ sai là xếp van một chiều vào nhóm áp suất.', '[{"term": "油圧バルブ", "reading": "ゆあつバルブ", "meaning": "Van thủy lực"}, {"term": "のうち", "reading": "のうち", "meaning": "Trong số…"}, {"term": "圧力制御弁", "reading": "あつりょくせいぎょべん", "meaning": "Van điều khiển áp suất"}, {"term": "チェック弁", "reading": "チェックべん", "meaning": "Van một chiều"}]'::jsonb, 85);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 26, '作動油において、温度による粘度の変化が大きいほど、粘度指数が高いといえる。', 'Đối với dầu thủy lực, độ nhớt thay đổi theo nhiệt độ càng lớn thì chỉ số độ nhớt càng cao.', FALSE, '粘度指数 — chỉ số độ nhớt càng cao thì độ nhớt càng ít thay đổi theo nhiệt độ. Thay đổi lớn tương ứng chỉ số thấp hơn, trái với đề. Giải thích chỉ số độ nhớt — ENEOS', '[{"term": "作動油", "reading": "さどうゆ", "meaning": "Dầu thủy lực"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "温度", "reading": "おんど", "meaning": "Nhiệt độ"}, {"term": "による", "reading": "による", "meaning": "Do; theo; dựa trên, tùy ngữ cảnh"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "変化", "reading": "へんか", "meaning": "Thay đổi; biến thiên"}, {"term": "大きい", "reading": "おおきい", "meaning": "Lớn"}, {"term": "ほど", "reading": "ほど", "meaning": "Càng…; mức độ…"}, {"term": "粘度指数", "reading": "ねんどしすう", "meaning": "Chỉ số độ nhớt"}, {"term": "高い", "reading": "たかい", "meaning": "Cao"}, {"term": "といえる", "reading": "といえる", "meaning": "Có thể nói rằng…"}]'::jsonb, 86);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 27, 'セラミックスとは、人為的な処理によって製造された非金属・無機質の固体材料である。', 'Gốm kỹ thuật là vật liệu rắn vô cơ, phi kim loại được sản xuất bằng xử lý nhân tạo.', TRUE, 'Mệnh đề phù hợp với cách định nghĩa セラミックス trong phạm vi kiến thức cơ bản. Những đặc tính thường gặp là chịu nhiệt, cứng và chống mài mòn, nhưng thay đổi theo loại vật liệu. Không đồng nhất mọi gốm với nhựa hoặc kim loại.', '[{"term": "セラミックス", "reading": "セラミックス", "meaning": "Gốm; vật liệu gốm kỹ thuật"}, {"term": "人為的", "reading": "じんいてき", "meaning": "Do con người tạo ra; nhân tạo"}, {"term": "処理", "reading": "しょり", "meaning": "Xử lý"}, {"term": "によって", "reading": "によって", "meaning": "Bằng; do; tùy theo, tùy ngữ cảnh"}, {"term": "製造", "reading": "せいぞう", "meaning": "Sản xuất; chế tạo"}, {"term": "非金属", "reading": "ひきんぞく", "meaning": "Phi kim loại"}, {"term": "無機質", "reading": "むきしつ", "meaning": "Vô cơ"}, {"term": "固体材料", "reading": "こたいざいりょう", "meaning": "Vật liệu rắn"}]'::jsonb, 87);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 28, 'ショットピーニングは、金属の表面層に球形に近い硬質粒子を高速度で打ち当てることによっ て、表面を加工硬化させる加工法である。', 'Phun bi tăng bền là phương pháp bắn hạt cứng gần hình cầu ở tốc độ cao lên lớp bề mặt kim loại để làm bề mặt biến cứng.', TRUE, 'ショットピーニング tạo biến dạng dẻo tại bề mặt và có thể tạo ứng suất dư nén có lợi cho độ bền mỏi. Mệnh đề về biến cứng bề mặt là đúng. Phân biệt mục đích tăng bền của shot peening với việc chỉ làm sạch bề mặt.', '[{"term": "ショットピーニング", "reading": "ショットピーニング", "meaning": "Phun bi tăng bền"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "表面層", "reading": "ひょうめんそう", "meaning": "Lớp bề mặt"}, {"term": "球形", "reading": "きゅうけい", "meaning": "Hình cầu"}, {"term": "近い", "reading": "ちかい", "meaning": "Gần; gần giống"}, {"term": "硬質粒子", "reading": "こうしつりゅうし", "meaning": "Hạt cứng"}, {"term": "高速度", "reading": "こうそくど", "meaning": "Tốc độ cao"}, {"term": "打ち当てる", "reading": "うちあてる", "meaning": "Bắn/đập vào"}, {"term": "によって", "reading": "によって", "meaning": "Bằng; do; tùy theo, tùy ngữ cảnh"}, {"term": "表面", "reading": "ひょうめん", "meaning": "Bề mặt"}, {"term": "加工硬化", "reading": "かこうこうか", "meaning": "Biến cứng do gia công biến dạng"}, {"term": "加工法", "reading": "かこうほう", "meaning": "Phương pháp gia công"}]'::jsonb, 88);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 29, '力が作用して物体を移動させたときの仕事は、作用した力と、力を作用させた距離との積で 表される。', 'Khi lực tác dụng làm vật dịch chuyển, công được biểu diễn bằng tích của lực và quãng đường tác dụng lực.', TRUE, 'Trong trường hợp cơ bản lực không đổi và cùng hướng dịch chuyển, W = F × s, đơn vị N·m = J. Nếu có góc θ giữa lực và dịch chuyển thì W = F × s × cosθ. Cách diễn đạt cơ bản của đề được chấm đúng; không nhầm quãng đường với thời gian.', '[{"term": "力", "reading": "ちから", "meaning": "Lực"}, {"term": "作用", "reading": "さよう", "meaning": "Tác dụng"}, {"term": "物体", "reading": "ぶったい", "meaning": "Vật thể"}, {"term": "移動", "reading": "いどう", "meaning": "Dịch chuyển"}, {"term": "仕事", "reading": "しごと", "meaning": "Công cơ học trong câu này"}, {"term": "距離", "reading": "きょり", "meaning": "Khoảng cách; quãng đường"}, {"term": "積", "reading": "せき", "meaning": "Tích (phép nhân)"}, {"term": "表される", "reading": "あらわされる", "meaning": "Được biểu diễn"}]'::jsonb, 89);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', NULL, 30, 'JISにおいて、寸法線を描くには、細い実線を用いる。', 'Theo JIS, đường kích thước được vẽ bằng nét liền mảnh.', TRUE, '寸法線 là đường biểu diễn kích thước và dùng nét liền mảnh. Không nhầm với nét liền đậm biểu diễn đường bao thấy của vật thể. Câu hỏi tập trung vào loại nét dùng cho đường kích thước.', '[{"term": "JIS", "reading": "ジス", "meaning": "Tiêu chuẩn công nghiệp Nhật Bản"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "寸法線", "reading": "すんぽうせん", "meaning": "Đường kích thước"}, {"term": "描く", "reading": "かく", "meaning": "Vẽ"}, {"term": "細い", "reading": "ほそい", "meaning": "Mảnh; nhỏ theo bề ngang"}, {"term": "実線", "reading": "じっせん", "meaning": "Nét liền"}, {"term": "用いる", "reading": "もちいる", "meaning": "Dùng; sử dụng"}, {"term": "Bảng", "reading": "đáp", "meaning": "án nhanh — 2025"}, {"term": "Câu", "reading": "Đáp", "meaning": "án Câu Đáp án Câu Đáp án"}, {"term": "1", "reading": "×", "meaning": "11 ○ 21 ×"}, {"term": "2", "reading": "×", "meaning": "12 × 22 ○"}, {"term": "3", "reading": "○", "meaning": "13 ○ 23 ○"}, {"term": "4", "reading": "×", "meaning": "14 × 24 ×"}, {"term": "5", "reading": "×", "meaning": "15 × 25 ×"}, {"term": "6", "reading": "○", "meaning": "16 ○ 26 ×"}, {"term": "7", "reading": "○", "meaning": "17 × 27 ○"}, {"term": "8", "reading": "×", "meaning": "18 × 28 ○"}, {"term": "9", "reading": "○", "meaning": "19 ○ 29 ○"}, {"term": "10", "reading": "×", "meaning": "20 ○ 30 ○"}, {"term": "PHẦN", "reading": "4", "meaning": "— ĐỀ NĂM 2026"}, {"term": "Kỳ", "reading": "thi:", "meaning": "第1回・機械系保全作業・3級 学科試験. Ngày thi: 21/06/2026."}]'::jsonb, 90);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 1, '下図に示す工作機械は、旋盤である。', 'Máy công cụ trong hình dưới là máy tiện.', TRUE, 'Hình có mâm cặp/đầu máy ở bên trái, băng máy nằm ngang, bàn dao và ụ động phía phải: đó là 旋盤 — máy tiện. Câu 1 năm 2025 có cùng lời đề nhưng hình khác và đáp án khác. Phải quan sát hình thay vì học thuộc lời câu hỏi.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}, {"term": "旋盤", "reading": "せんばん", "meaning": "Máy tiện"}]'::jsonb, 91);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 2, 'ボール盤とは、工作物を固定して、主軸に取り付けた切削工具を回転させながら穴あけ加工 を行う工作機械である。', 'Máy khoan là máy công cụ khoan lỗ bằng cách cố định phôi và quay dụng cụ cắt gắn trên trục chính.', TRUE, 'Đây là nguyên lý cơ bản của ボール盤. Phôi được gá cố định, mũi khoan quay và tiến vào phôi để tạo lỗ. Phân biệt với tiện, nơi phôi thường quay.', '[{"term": "ボール盤", "reading": "ボールばん", "meaning": "Máy khoan"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "Phôi; vật gia công"}, {"term": "固定", "reading": "こてい", "meaning": "Cố định"}, {"term": "主軸", "reading": "しゅじく", "meaning": "Trục chính"}, {"term": "取り付け", "reading": "とりつけ", "meaning": "Lắp; gắn (dạng nối câu của 取り付ける)"}, {"term": "切削工具", "reading": "せっさくこうぐ", "meaning": "Dụng cụ cắt"}, {"term": "回転", "reading": "かいてん", "meaning": "Chuyển động quay"}, {"term": "させながら", "reading": "させながら", "meaning": "Vừa cho/làm cho… vừa…"}, {"term": "穴あけ加工", "reading": "あなあけかこう", "meaning": "Gia công tạo lỗ; khoan lỗ"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "工作機械", "reading": "こうさくきかい", "meaning": "Máy công cụ"}]'::jsonb, 92);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 3, '下図に示す回路における抵抗Rは、10Ωである。', 'Điện trở R trong mạch dưới là 10 Ω.', FALSE, 'Nguồn 10 V tạo dòng 1 A, nên điện trở toàn mạch Rt = U/I = 10/1 = 10 Ω. R mắc nối tiếp với điện trở 5 Ω, do đó R + 5 = 10 và R = 5 Ω. Đề nhầm điện trở toàn mạch với điện trở R cần tìm.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "回路", "reading": "かいろ", "meaning": "Mạch điện; mạch hệ thống, tùy ngữ cảnh"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "抵抗", "reading": "ていこう", "meaning": "Điện trở trong câu mạch điện"}, {"term": "Ω", "reading": "オーム", "meaning": "Ôm; đơn vị điện trở"}]'::jsonb, 93);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 4, '60Hzで使用している三相誘導電動機を50Hzで使用すると、回転数は6/5倍になる。', 'Khi dùng động cơ không đồng bộ ba pha đang chạy ở 60 Hz với nguồn 50 Hz, tốc độ quay trở thành 6/5 lần.', FALSE, 'Với số cực không đổi, tỷ số tốc độ đồng bộ là 50/60 = 5/6, không phải 6/5. Tốc độ rôto thực còn chịu ảnh hưởng độ trượt; ở mức so sánh cơ bản của đề, giảm tần số làm tốc độ giảm. Công thức tốc độ đồng bộ — Oriental Motor', '[{"term": "Hz", "reading": "ヘルツ", "meaning": "Héc; đơn vị tần số"}, {"term": "使用", "reading": "しよう", "meaning": "Sử dụng"}, {"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "Động cơ không đồng bộ ba pha"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "Số vòng quay; trong câu này là tốc độ quay"}, {"term": "倍", "reading": "ばい", "meaning": "Lần; bội số"}, {"term": "になる", "reading": "になる", "meaning": "Trở thành; thay đổi thành"}]'::jsonb, 94);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 5, '改良保全とは、設備の故障を起きにくくしたり、設備の性能や安全性を高める保全である。', 'Bảo trì cải tiến là bảo trì nhằm làm thiết bị khó hỏng hơn hoặc nâng cao tính năng và độ an toàn.', TRUE, '改良保全 tác động vào thiết kế/cấu tạo hoặc đặc điểm thiết bị để khắc phục điểm yếu. Mục tiêu có thể là giảm hỏng, tăng an toàn hoặc cải thiện khả năng bảo trì. Vì vậy định nghĩa trong đề đúng.', '[{"term": "改良保全", "reading": "かいりょうほぜん", "meaning": "Bảo trì cải tiến"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "起きにくく", "reading": "おきにくく", "meaning": "Khó xảy ra hơn (dạng của 起きにくい)"}, {"term": "性能", "reading": "せいのう", "meaning": "Tính năng; hiệu năng"}, {"term": "安全性", "reading": "あんぜんせい", "meaning": "Tính an toàn"}, {"term": "高める", "reading": "たかめる", "meaning": "Nâng cao"}, {"term": "保全", "reading": "ほぜん", "meaning": "Bảo trì"}]'::jsonb, 95);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 6, '平均故障寿命とは、故障した設備が修理されてから、次に故障するまでの動作時間の平均値 である。', 'Tuổi thọ trung bình đến hỏng là trung bình thời gian hoạt động từ lúc thiết bị hỏng được sửa xong đến khi hỏng tiếp theo.', FALSE, '平均故障寿命 — MTTF là thời gian trung bình đến khi hỏng, thường dùng cho đối tượng không sửa chữa. Khoảng hoạt động giữa các lần hỏng của đối tượng sửa chữa được thuộc khái niệm 平均故障間隔 — MTBF trong cách phân biệt cơ bản của đề. Chỗ sai là gán mô tả “sửa xong rồi hỏng tiếp” cho MTTF.', '[{"term": "平均故障寿命", "reading": "へいきんこしょうじゅみょう", "meaning": "Tuổi thọ trung bình đến hỏng; MTTF"}, {"term": "故障", "reading": "こしょう", "meaning": "Hỏng; mất chức năng yêu cầu"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "修理", "reading": "しゅうり", "meaning": "Sửa chữa"}, {"term": "次に", "reading": "つぎに", "meaning": "Tiếp theo"}, {"term": "まで", "reading": "まで", "meaning": "Đến; cho tới"}, {"term": "動作時間", "reading": "どうさじかん", "meaning": "Thời gian hoạt động"}, {"term": "平均値", "reading": "へいきんち", "meaning": "Giá trị trung bình"}]'::jsonb, 96);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 7, '予知保全とは、過去の故障実績などを参考にし、一定の周期で点検や検査を行う保全である。', 'Bảo trì dự đoán là bảo trì thực hiện kiểm tra theo chu kỳ cố định dựa vào lịch sử hỏng.', FALSE, 'Chu kỳ cố định dựa trên lịch sử là cách lập bảo trì theo thời gian/định kỳ. 予知保全 dùng dữ liệu tình trạng như rung, nhiệt độ hoặc phân tích dầu để dự đoán diễn biến và nhu cầu bảo trì. Chỗ sai cần nhớ là 一定の周期 — chu kỳ cố định.', '[{"term": "予知保全", "reading": "よちほぜん", "meaning": "Bảo trì dự đoán"}, {"term": "過去", "reading": "かこ", "meaning": "Quá khứ"}, {"term": "故障実績", "reading": "こしょうじっせき", "meaning": "Dữ liệu/lịch sử hỏng thực tế"}, {"term": "参考", "reading": "さんこう", "meaning": "Tham khảo"}, {"term": "一定", "reading": "いってい", "meaning": "Cố định; nhất định"}, {"term": "周期", "reading": "しゅうき", "meaning": "Chu kỳ"}, {"term": "点検", "reading": "てんけん", "meaning": "Kiểm tra tình trạng"}, {"term": "検査", "reading": "けんさ", "meaning": "Kiểm tra; kiểm nghiệm"}, {"term": "行う", "reading": "おこなう", "meaning": "Thực hiện"}, {"term": "保全", "reading": "ほぜん", "meaning": "Bảo trì"}]'::jsonb, 97);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 8, 'なぜなぜ分析は、発生した現象を起点として、その現象がなぜ起きたのかを繰り返し調査し ていくことで、対策を立てる手法である。', 'Phân tích “tại sao” là phương pháp bắt đầu từ hiện tượng đã xảy ra, lặp lại điều tra tại sao nó xảy ra để xây dựng biện pháp.', TRUE, 'なぜなぜ分析 đặt câu hỏi “tại sao” nhiều lần để đi từ hiện tượng đến nguyên nhân sâu hơn. Các câu trả lời cần dựa trên bằng chứng, không chỉ suy đoán. Mục tiêu là tìm biện pháp xử lý nguyên nhân phù hợp.', '[{"term": "なぜなぜ分析", "reading": "なぜなぜぶんせき", "meaning": "Phân tích “tại sao” lặp lại để tìm nguyên"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "現象", "reading": "げんしょう", "meaning": "Hiện tượng"}, {"term": "起点", "reading": "きてん", "meaning": "Điểm xuất phát"}, {"term": "なぜ", "reading": "なぜ", "meaning": "Tại sao"}, {"term": "繰り返し", "reading": "くりかえし", "meaning": "Lặp lại"}, {"term": "調査", "reading": "ちょうさ", "meaning": "Điều tra; khảo sát"}, {"term": "対策", "reading": "たいさく", "meaning": "Biện pháp xử lý/phòng ngừa"}, {"term": "立てる", "reading": "たてる", "meaning": "Lập; xây dựng (kế hoạch, biện pháp)"}, {"term": "手法", "reading": "しゅほう", "meaning": "Phương pháp; cách tiếp cận"}]'::jsonb, 98);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 9, '下図に示すような品質管理の手法は、特性要因図である。', 'Phương pháp quản lý chất lượng trong hình dưới là biểu đồ nguyên nhân–kết quả.', TRUE, 'Hình dạng xương cá có các nhánh 人, 機械, 方法, 材料 hướng đến 結果. Đây là 特性要因図, dùng để hệ thống hóa yếu tố có thể ảnh hưởng kết quả. Không nhầm với パレート図 — biểu đồ Pareto hoặc ヒストグラム — biểu đồ phân bố tần số.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "品質管理", "reading": "ひんしつかんり", "meaning": "Quản lý chất lượng"}, {"term": "手法", "reading": "しゅほう", "meaning": "Phương pháp; cách tiếp cận"}, {"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "Biểu đồ nguyên nhân–kết quả; biểu đồ"}]'::jsonb, 99);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 10, '正規分布の特徴の1つとして、データが平均値の付近に集積していることが挙げられる。', 'Một đặc điểm của phân bố chuẩn là dữ liệu tập trung gần giá trị trung bình.', TRUE, '正規分布 có dạng chuông, đối xứng quanh trung bình. Mật độ lớn nhất ở gần trung bình và nhỏ hơn khi đi xa về hai phía. Điều này không có nghĩa mọi dữ liệu đều nằm sát trung bình.', '[{"term": "正規分布", "reading": "せいきぶんぷ", "meaning": "Phân bố chuẩn"}, {"term": "特徴", "reading": "とくちょう", "meaning": "Đặc điểm"}, {"term": "データ", "reading": "データ", "meaning": "Dữ liệu"}, {"term": "平均値", "reading": "へいきんち", "meaning": "Giá trị trung bình"}, {"term": "付近", "reading": "ふきん", "meaning": "Vùng gần; lân cận"}, {"term": "集積", "reading": "しゅうせき", "meaning": "Tập trung; tích tụ"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 100);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 11, '一般的に鉄は、銅よりも耐食性に優れる。', 'Thông thường, sắt chống ăn mòn tốt hơn đồng.', FALSE, 'Trong so sánh cơ bản ở môi trường thông thường, sắt dễ bị gỉ hơn đồng. Khả năng chống ăn mòn thực tế phụ thuộc môi trường, hợp kim và xử lý bề mặt, nhưng phát biểu “sắt nói chung tốt hơn đồng” là sai trong câu này. Không nhầm sắt thông thường với thép không gỉ.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "鉄", "reading": "てつ", "meaning": "Sắt"}, {"term": "銅", "reading": "どう", "meaning": "Đồng"}, {"term": "より", "reading": "より", "meaning": "So với; hơn (dùng khi so sánh)"}, {"term": "耐食性", "reading": "たいしょくせい", "meaning": "Khả năng chống ăn mòn"}, {"term": "優れる", "reading": "すぐれる", "meaning": "Vượt trội; tốt hơn"}]'::jsonb, 101);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 12, 'ステンレス鋼は、鉄にニッケルと亜鉛を加えて性質を改良したものである。', 'Thép không gỉ là thép cải thiện tính chất bằng cách thêm niken và kẽm vào sắt.', FALSE, 'Nguyên tố nền tảng tạo tính không gỉ là crôm, không phải tổ hợp niken và kẽm. Thép không gỉ có tối thiểu khoảng 10,5% crôm theo định nghĩa phổ biến; niken có trong một số nhóm nhưng không phải mọi loại. Định nghĩa thép không gỉ — worldstainless', '[{"term": "ステンレス鋼", "reading": "ステンレスこう", "meaning": "Thép không gỉ"}, {"term": "鉄", "reading": "てつ", "meaning": "Sắt"}, {"term": "ニッケル", "reading": "ニッケル", "meaning": "Niken"}, {"term": "亜鉛", "reading": "あえん", "meaning": "Kẽm"}, {"term": "加えて", "reading": "くわえて", "meaning": "Thêm vào (dạng của 加える)"}, {"term": "性質", "reading": "せいしつ", "meaning": "Tính chất"}, {"term": "改良", "reading": "かいりょう", "meaning": "Cải tiến; cải thiện"}]'::jsonb, 102);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 13, '金属の熱処理は、加熱温度や冷却速度などを調節することにより、性質や金属組織を改良す る加工方法である。', 'Nhiệt luyện kim loại là phương pháp cải thiện tính chất và tổ chức kim loại bằng điều chỉnh nhiệt độ gia nhiệt, tốc độ làm nguội và các điều kiện khác.', TRUE, '熱処理 dùng chế độ nhiệt phù hợp để thay đổi tổ chức và tính chất vật liệu. Tôi, ram, ủ và thường hóa là những ví dụ. Đề mô tả nguyên lý chung đúng.', '[{"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "熱処理", "reading": "ねつしょり", "meaning": "Nhiệt luyện"}, {"term": "加熱温度", "reading": "かねつおんど", "meaning": "Nhiệt độ gia nhiệt"}, {"term": "冷却速度", "reading": "れいきゃくそくど", "meaning": "Tốc độ làm nguội"}, {"term": "調節", "reading": "ちょうせつ", "meaning": "Điều chỉnh"}, {"term": "性質", "reading": "せいしつ", "meaning": "Tính chất"}, {"term": "金属組織", "reading": "きんぞくそしき", "meaning": "Tổ chức kim loại"}, {"term": "改良", "reading": "かいりょう", "meaning": "Cải tiến; cải thiện"}, {"term": "加工方法", "reading": "かこうほうほう", "meaning": "Phương pháp gia công"}]'::jsonb, 103);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 14, '労働災害とは、労働者の就業に係る建設物や設備などにより、または作業行動その他の業務 に起因して、労働者が負傷し、疾病にかかり、または死亡することをいう。', 'Tai nạn lao động là việc người lao động bị thương, mắc bệnh hoặc tử vong do công trình, thiết bị gắn với công việc hoặc do hành động làm việc và nguyên nhân nghiệp vụ khác.', TRUE, 'Mệnh đề nêu đúng trọng tâm của 労働災害: hậu quả đối với người lao động có nguồn gốc từ công việc. Đây không chỉ là hỏng thiết bị hoặc thiên tai nói chung. Định nghĩa — Bộ Y tế, Lao động và Phúc lợi Nhật Bản', '[{"term": "労働災害", "reading": "ろうどうさいがい", "meaning": "Tai nạn, bệnh tật hoặc tử vong do lao động"}, {"term": "労働者", "reading": "ろうどうしゃ", "meaning": "Người lao động"}, {"term": "就業", "reading": "しゅうぎょう", "meaning": "Làm việc; thực hiện công việc"}, {"term": "係る", "reading": "かかる", "meaning": "Liên quan đến"}, {"term": "建設物", "reading": "けんせつぶつ", "meaning": "Công trình xây dựng"}, {"term": "設備", "reading": "せつび", "meaning": "Thiết bị; hệ thống thiết bị"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "作業行動", "reading": "さぎょうこうどう", "meaning": "Hành động/thao tác làm việc"}, {"term": "その他", "reading": "そのた", "meaning": "Khác; ngoài ra"}, {"term": "業務", "reading": "ぎょうむ", "meaning": "Công việc; hoạt động nghiệp vụ"}, {"term": "起因", "reading": "きいん", "meaning": "Bắt nguồn từ; do nguyên nhân"}, {"term": "負傷", "reading": "ふしょう", "meaning": "Bị thương"}, {"term": "疾病", "reading": "しっぺい", "meaning": "Bệnh tật"}, {"term": "かかり", "reading": "かかり", "meaning": "Mắc (bệnh); dạng nối câu của かかる"}, {"term": "死亡", "reading": "しぼう", "meaning": "Tử vong"}]'::jsonb, 104);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 15, '5Sにおける整頓とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, “sắp xếp” là phân chia thứ cần thiết và không cần thiết rồi loại bỏ thứ không cần.', FALSE, 'Đó là 整理 — sàng lọc, không phải 整頓 — sắp xếp. 整頓 là tổ chức thứ cần thiết ở vị trí thích hợp để dễ lấy và trả lại. Câu này giống câu 15 năm 2025 và đều sai.', '[{"term": "5S", "reading": "ごエス", "meaning": "5S: sàng lọc, sắp xếp, sạch sẽ, duy trì sạch"}, {"term": "sẽ,", "reading": "rèn", "meaning": "nề nếp"}, {"term": "における", "reading": "における", "meaning": "Trong; tại; xét trong"}, {"term": "整頓", "reading": "せいとん", "meaning": "Sắp xếp thứ cần thiết để dễ tìm, lấy và trả"}, {"term": "必要", "reading": "ひつよう", "meaning": "Cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "Không cần thiết"}, {"term": "区分", "reading": "くぶん", "meaning": "Phân chia; phân loại"}, {"term": "なくす", "reading": "なくす", "meaning": "Loại bỏ; làm cho không còn"}]'::jsonb, 105);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 16, 'おねじとは、ねじ山が円筒または円錐の外側にあるねじである。', 'Ren ngoài là ren có đỉnh ren ở bên ngoài hình trụ hoặc hình côn.', TRUE, 'おねじ là ren ngoài, ví dụ phần có ren của bu lông. めねじ là ren trong, ví dụ ren trong đai ốc. Mô tả của đề đúng.', '[{"term": "おねじ", "reading": "おねじ", "meaning": "Ren ngoài"}, {"term": "ねじ山", "reading": "ねじやま", "meaning": "Gờ ren; phần nhô của ren"}, {"term": "円筒", "reading": "えんとう", "meaning": "Hình trụ"}, {"term": "または", "reading": "または", "meaning": "Hoặc"}, {"term": "円錐", "reading": "えんすい", "meaning": "Hình nón; hình côn"}, {"term": "外側", "reading": "そとがわ", "meaning": "Phía ngoài"}, {"term": "ねじ", "reading": "ねじ", "meaning": "Ren; vít, tùy ngữ cảnh"}]'::jsonb, 106);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 17, 'かさ歯車同士の噛み合いでは、2つの歯車の軸が平行になる。', 'Khi hai bánh răng côn ăn khớp, hai trục bánh răng trở thành song song.', FALSE, 'かさ歯車 thông thường dùng cho hai trục giao nhau; hay gặp góc 90° nhưng không bắt buộc luôn 90°. Trục song song là đặc trưng của bộ bánh răng trụ như 平歯車. Chỗ sai là 平行 — song song.', '[{"term": "かさ歯車", "reading": "かさはぐるま", "meaning": "Bánh răng côn"}, {"term": "同士", "reading": "どうし", "meaning": "Giữa những đối tượng cùng loại"}, {"term": "噛み合い", "reading": "かみあい", "meaning": "Sự ăn khớp"}, {"term": "歯車", "reading": "はぐるま", "meaning": "Bánh răng"}, {"term": "軸", "reading": "じく", "meaning": "Trục"}, {"term": "平行", "reading": "へいこう", "meaning": "Song song"}, {"term": "になる", "reading": "になる", "meaning": "Trở thành; thay đổi thành"}]'::jsonb, 107);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 18, '下図に示す測定器は、マイクロメータである。', 'Dụng cụ đo trong hình dưới là panme.', FALSE, 'Hình là ノギス — thước cặp, với mỏ đo, thước chính và bộ phận trượt. Panme thường có khung dạng chữ C, đầu đo và cơ cấu vít vi cấp, khác hình này. Vì vậy đáp án là sai.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "測定器", "reading": "そくていき", "meaning": "Dụng cụ/thiết bị đo"}, {"term": "マイクロメータ", "reading": "マイクロメータ", "meaning": "Panme"}]'::jsonb, 108);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 19, '軸受に発生する腐食の主な原因として、軸受に作用する過大な荷重が挙げられる。', 'Một nguyên nhân chính của ăn mòn ổ trục là tải trọng quá lớn tác dụng lên ổ trục.', FALSE, 'Ăn mòn/gỉ ổ trục thường liên quan nước, hơi ẩm, môi trường ăn mòn hoặc bảo quản không phù hợp. Tải quá lớn chủ yếu liên quan hư hại cơ học như biến dạng hoặc mỏi, không phải nguyên nhân chính của ăn mòn trong câu hỏi này. Nguyên nhân gỉ và ăn mòn ổ trục — NSK', '[{"term": "軸受", "reading": "じくうけ", "meaning": "Ổ trục; ổ đỡ"}, {"term": "発生", "reading": "はっせい", "meaning": "Phát sinh; xảy ra"}, {"term": "腐食", "reading": "ふしょく", "meaning": "Ăn mòn"}, {"term": "主な", "reading": "おもな", "meaning": "Chủ yếu; chính"}, {"term": "原因", "reading": "げんいん", "meaning": "Nguyên nhân"}, {"term": "作用", "reading": "さよう", "meaning": "Tác dụng"}, {"term": "過大", "reading": "かだい", "meaning": "Quá lớn; vượt mức"}, {"term": "荷重", "reading": "かじゅう", "meaning": "Tải trọng"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "Được nêu ra; được kể đến"}]'::jsonb, 109);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 20, 'ちょう度とは、グリースの硬さを数値化したものである。', 'Độ xuyên kim là đại lượng số hóa độ cứng của mỡ bôi trơn.', TRUE, 'ちょう度 biểu thị độ mềm/cứng, hay độ đặc của mỡ theo phép đo độ xuyên kim. Giá trị độ xuyên kim càng lớn thì mỡ càng mềm. Không nhầm với 粘度 — độ nhớt của chất lỏng; cũng không nhầm trị số xuyên kim với số cấp NLGI.', '[{"term": "ちょう度", "reading": "ちょうど", "meaning": "Độ đặc/mềm cứng của mỡ, biểu thị bằng"}, {"term": "độ", "reading": "xuyên", "meaning": "kim"}, {"term": "グリース", "reading": "グリース", "meaning": "Mỡ bôi trơn"}, {"term": "硬さ", "reading": "かたさ", "meaning": "Độ cứng"}, {"term": "数値化", "reading": "すうちか", "meaning": "Biểu thị bằng số; định lượng"}]'::jsonb, 110);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 21, 'ガス溶接とは、2つの母材の接合部分と溶加材を燃焼ガスの炎で加熱して溶融することで、 接合する方法である。', 'Hàn khí là phương pháp nối hai vật liệu cơ bản bằng cách dùng ngọn lửa khí cháy làm nóng chảy vị trí nối và vật liệu bổ sung.', TRUE, 'ガス溶接 sử dụng nhiệt từ ngọn lửa khí, ví dụ oxy–axetylen. Trong trường hợp đề mô tả, nhiệt làm nóng chảy vùng nối và vật liệu bổ sung để tạo mối hàn. Phân biệt với hàn điểm điện trở và hàn hồ quang.', '[{"term": "ガス溶接", "reading": "ガスようせつ", "meaning": "Hàn khí"}, {"term": "母材", "reading": "ぼざい", "meaning": "Vật liệu cơ bản/vật liệu nền được nối"}, {"term": "接合部分", "reading": "せつごうぶぶん", "meaning": "Vị trí/phần nối"}, {"term": "溶加材", "reading": "ようかざい", "meaning": "Vật liệu bổ sung khi hàn"}, {"term": "燃焼ガス", "reading": "ねんしょうガス", "meaning": "Khí cháy"}, {"term": "炎", "reading": "ほのお", "meaning": "Ngọn lửa"}, {"term": "加熱", "reading": "かねつ", "meaning": "Gia nhiệt"}, {"term": "溶融", "reading": "ようゆう", "meaning": "Nóng chảy"}, {"term": "接合", "reading": "せつごう", "meaning": "Nối; ghép"}, {"term": "方法", "reading": "ほうほう", "meaning": "Phương pháp"}]'::jsonb, 111);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 22, '鋳造とは、鋳型に溶かした金属を注ぎ込み、冷却により凝固させる工作法である。', 'Đúc là phương pháp rót kim loại nóng chảy vào khuôn rồi làm nguội cho đông đặc.', TRUE, 'Đây là nguyên lý của 鋳造. 鋳型 là khuôn đúc; 凝固 là đông đặc. Không nhầm với 鍛造 — rèn, là tạo hình bằng lực tác dụng lên kim loại.', '[{"term": "鋳造", "reading": "ちゅうぞう", "meaning": "Đúc"}, {"term": "鋳型", "reading": "いがた", "meaning": "Khuôn đúc"}, {"term": "溶かした", "reading": "とかした", "meaning": "Đã làm nóng chảy (dạng của 溶かす)"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "注ぎ込み", "reading": "そそぎこみ", "meaning": "Rót vào (dạng nối câu của 注ぎ込む)"}, {"term": "冷却", "reading": "れいきゃく", "meaning": "Làm nguội"}, {"term": "により", "reading": "により", "meaning": "Do; bởi; nhờ, tùy ngữ cảnh"}, {"term": "凝固", "reading": "ぎょうこ", "meaning": "Đông đặc"}, {"term": "工作法", "reading": "こうさくほう", "meaning": "Phương pháp chế tạo/gia công"}]'::jsonb, 112);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 23, '非破壊試験には、浸透探傷試験や超音波探傷試験などがある。', 'Kiểm tra không phá hủy gồm kiểm tra thẩm thấu và kiểm tra siêu âm.', TRUE, '浸透探傷試験 dùng chất thẩm thấu để phát hiện khuyết tật hở ra bề mặt; 超音波探傷試験 dùng sóng siêu âm để khảo sát khuyết tật theo phương pháp phù hợp. Đây là những phép thử không phá hủy. Đề dùng 非破壊試験; về chủ đề học có liên quan trực tiếp đến 非破壊検査.', '[{"term": "非破壊試験", "reading": "ひはかいしけん", "meaning": "Thử nghiệm không phá hủy"}, {"term": "浸透探傷試験", "reading": "しんとうたんしょうしけん", "meaning": "Kiểm tra khuyết tật bằng chất thẩm thấu"}, {"term": "超音波探傷試験", "reading": "ちょうおんぱたんしょうしけん", "meaning": "Kiểm tra khuyết tật bằng siêu âm"}]'::jsonb, 113);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 24, '一般的に、油圧は空気圧に比べて、精密な速度制御が困難である。', 'Thông thường, thủy lực khó điều khiển tốc độ chính xác hơn khí nén.', FALSE, 'Dầu có độ nén nhỏ hơn không khí nên thủy lực thường thuận lợi hơn khi cần chuyển động ổn định và điều khiển tốc độ chính xác. Khí nén có tính đàn hồi/nén được nên tốc độ dễ bị ảnh hưởng bởi tải và biến động áp suất. Đề đảo ngược xu hướng so sánh chung; tính năng cụ thể còn phụ thuộc thiết kế hệ thống.', '[{"term": "一般的に", "reading": "いっぱんてきに", "meaning": "Thông thường; nói chung"}, {"term": "油圧", "reading": "ゆあつ", "meaning": "Thủy lực dùng dầu"}, {"term": "空気圧", "reading": "くうきあつ", "meaning": "Khí nén"}, {"term": "比べ", "reading": "くらべ", "meaning": "So sánh; so với (dạng nối câu của 比べる)"}, {"term": "精密", "reading": "せいみつ", "meaning": "Chính xác; tinh mật"}, {"term": "速度制御", "reading": "そくどせいぎょ", "meaning": "Điều khiển tốc độ"}, {"term": "困難", "reading": "こんなん", "meaning": "Khó khăn"}]'::jsonb, 114);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 25, '油圧バルブのうち、方向制御弁には、リリーフ弁やアンロード弁などがある。', 'Trong các van thủy lực, van điều khiển hướng gồm van tràn và van xả tải.', FALSE, 'リリーフ弁 và アンロード弁 thuộc nhóm van điều khiển áp suất theo phân loại chức năng cơ bản. Van điều khiển hướng dùng để chọn hoặc thay đổi đường đi dòng chảy. Đề xếp sai nhóm van.', '[{"term": "油圧バルブ", "reading": "ゆあつバルブ", "meaning": "Van thủy lực"}, {"term": "のうち", "reading": "のうち", "meaning": "Trong số…"}, {"term": "方向制御弁", "reading": "ほうこうせいぎょべん", "meaning": "Van điều khiển hướng"}, {"term": "リリーフ弁", "reading": "リリーフべん", "meaning": "Van tràn; van giới hạn áp suất"}, {"term": "アンロード弁", "reading": "アンロードべん", "meaning": "Van xả tải"}]'::jsonb, 115);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 26, '作動油において、温度による粘度の変化が大きいほど、粘度指数が低いといえる。', 'Đối với dầu thủy lực, độ nhớt thay đổi theo nhiệt độ càng lớn thì chỉ số độ nhớt càng thấp.', TRUE, '粘度指数 cao nghĩa là độ nhớt ít nhạy với thay đổi nhiệt độ; chỉ số thấp nghĩa là thay đổi nhiều hơn. Vì vậy mệnh đề này đúng và đối lập với câu 26 năm 2025. Giải thích chỉ số độ nhớt — ENEOS', '[{"term": "作動油", "reading": "さどうゆ", "meaning": "Dầu thủy lực"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "温度", "reading": "おんど", "meaning": "Nhiệt độ"}, {"term": "による", "reading": "による", "meaning": "Do; theo; dựa trên, tùy ngữ cảnh"}, {"term": "粘度", "reading": "ねんど", "meaning": "Độ nhớt"}, {"term": "変化", "reading": "へんか", "meaning": "Thay đổi; biến thiên"}, {"term": "大きい", "reading": "おおきい", "meaning": "Lớn"}, {"term": "ほど", "reading": "ほど", "meaning": "Càng…; mức độ…"}, {"term": "粘度指数", "reading": "ねんどしすう", "meaning": "Chỉ số độ nhớt"}, {"term": "低い", "reading": "ひくい", "meaning": "Thấp"}, {"term": "といえる", "reading": "といえる", "meaning": "Có thể nói rằng…"}]'::jsonb, 116);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 27, 'プラスチックとは、主に石油などから作られる合成樹脂のことである。', 'Nhựa là nhựa tổng hợp được sản xuất chủ yếu từ dầu mỏ và các nguyên liệu tương tự.', TRUE, 'Mệnh đề đúng trong phạm vi mô tả vật liệu thông dụng của đề. プラスチック là nhóm vật liệu dựa trên polymer/nhựa, thường từ nguyên liệu hóa dầu. Từ 主に nghĩa là “chủ yếu”, không khẳng định tất cả nhựa đều chỉ làm từ dầu mỏ.', '[{"term": "プラスチック", "reading": "プラスチック", "meaning": "Nhựa"}, {"term": "主に", "reading": "おもに", "meaning": "Chủ yếu"}, {"term": "石油", "reading": "せきゆ", "meaning": "Dầu mỏ"}, {"term": "合成樹脂", "reading": "ごうせいじゅし", "meaning": "Nhựa tổng hợp"}]'::jsonb, 117);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 28, 'ショットピーニングは、金属の表面層に球形に近い硬質粒子を高速度で打ち当てることによっ て、表面を加工硬化させる加工法である。', 'Phun bi tăng bền là phương pháp bắn hạt cứng gần hình cầu ở tốc độ cao lên lớp bề mặt kim loại để làm bề mặt biến cứng.', TRUE, 'ショットピーニング gây biến dạng dẻo tại bề mặt, làm biến cứng và có thể tạo ứng suất dư nén. Điều này thường được tận dụng để cải thiện độ bền mỏi. Câu giống câu 28 năm 2025 và đều đúng.', '[{"term": "ショットピーニング", "reading": "ショットピーニング", "meaning": "Phun bi tăng bền"}, {"term": "金属", "reading": "きんぞく", "meaning": "Kim loại"}, {"term": "表面層", "reading": "ひょうめんそう", "meaning": "Lớp bề mặt"}, {"term": "球形", "reading": "きゅうけい", "meaning": "Hình cầu"}, {"term": "近い", "reading": "ちかい", "meaning": "Gần; gần giống"}, {"term": "硬質粒子", "reading": "こうしつりゅうし", "meaning": "Hạt cứng"}, {"term": "高速度", "reading": "こうそくど", "meaning": "Tốc độ cao"}, {"term": "打ち当てる", "reading": "うちあてる", "meaning": "Bắn/đập vào"}, {"term": "によって", "reading": "によって", "meaning": "Bằng; do; tùy theo, tùy ngữ cảnh"}, {"term": "表面", "reading": "ひょうめん", "meaning": "Bề mặt"}, {"term": "加工硬化", "reading": "かこうこうか", "meaning": "Biến cứng do gia công biến dạng"}, {"term": "加工法", "reading": "かこうほう", "meaning": "Phương pháp gia công"}]'::jsonb, 118);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 29, '物体に力を加えて移動させたとき、その力がした仕事の大きさは、力の大きさと力を加えて いる間の時間の積で表される。', 'Khi lực làm vật dịch chuyển, công của lực được biểu diễn bằng tích của độ lớn lực và thời gian tác dụng.', FALSE, 'Công cơ học không phải lực nhân thời gian. Với lực không đổi, W = F × s × cosθ; khi cùng hướng dịch chuyển, W = F × s. Tích F × t thuộc khái niệm xung lượng của lực trong trường hợp lực không đổi, đơn vị N·s, khác công có đơn vị J.', '[{"term": "物体", "reading": "ぶったい", "meaning": "Vật thể"}, {"term": "力", "reading": "ちから", "meaning": "Lực"}, {"term": "加えて", "reading": "くわえて", "meaning": "Tác dụng lực lên (dạng của 加える)"}, {"term": "移動", "reading": "いどう", "meaning": "Dịch chuyển"}, {"term": "仕事", "reading": "しごと", "meaning": "Công cơ học trong câu này"}, {"term": "大きさ", "reading": "おおきさ", "meaning": "Độ lớn"}, {"term": "時間", "reading": "じかん", "meaning": "Thời gian"}, {"term": "積", "reading": "せき", "meaning": "Tích (phép nhân)"}, {"term": "表される", "reading": "あらわされる", "meaning": "Được biểu diễn"}]'::jsonb, 119);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', NULL, 30, '下図に示す図面において、Aを寸法補助線という。', 'Trong bản vẽ dưới, A được gọi là đường gióng kích thước.', FALSE, 'A chỉ vào đường dẫn từ phần ghi φ11 đến đặc điểm cần chỉ: đó là 引出線 — đường dẫn chú thích/leader line. 寸法補助線 là đường gióng kích thước kéo từ vị trí cần đo đến đường kích thước. Đáp án sai vì gọi nhầm loại đường; φ11 chỉ đường kính 11 mm.', '[{"term": "下図", "reading": "かず", "meaning": "Hình dưới"}, {"term": "示す", "reading": "しめす", "meaning": "Chỉ ra; thể hiện"}, {"term": "図面", "reading": "ずめん", "meaning": "Bản vẽ"}, {"term": "において", "reading": "において", "meaning": "Trong; xét đối với"}, {"term": "寸法補助線", "reading": "すんぽうほじょせん", "meaning": "Đường gióng kích thước"}, {"term": "という", "reading": "という", "meaning": "Gọi là; có tên là"}, {"term": "Bảng", "reading": "đáp", "meaning": "án nhanh — 2026"}, {"term": "Câu", "reading": "Đáp", "meaning": "án Câu Đáp án Câu Đáp án"}, {"term": "1", "reading": "○", "meaning": "11 × 21 ○"}, {"term": "2", "reading": "○", "meaning": "12 × 22 ○"}, {"term": "3", "reading": "×", "meaning": "13 ○ 23 ○"}, {"term": "4", "reading": "×", "meaning": "14 ○ 24 ×"}, {"term": "5", "reading": "○", "meaning": "15 × 25 ×"}, {"term": "6", "reading": "×", "meaning": "16 ○ 26 ○"}, {"term": "7", "reading": "×", "meaning": "17 × 27 ○"}, {"term": "8", "reading": "○", "meaning": "18 × 28 ○"}, {"term": "9", "reading": "○", "meaning": "19 × 29 ×"}, {"term": "10", "reading": "○", "meaning": "20 ○ 30 ×"}]'::jsonb, 120);
