-- Certificates feature: categories, vocabulary, and exam questions
-- Generated from doccument/kikaihozen3/*.pdf via a one-off parsing script

CREATE TABLE IF NOT EXISTS certificates (
    id SERIAL PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    category VARCHAR(50) NOT NULL,
    name_ja VARCHAR(200) NOT NULL,
    name_vi VARCHAR(200),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS certificate_vocabulary (
    id SERIAL PRIMARY KEY,
    certificate_id INT NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,
    category_no INT NOT NULL,
    category_name VARCHAR(200) NOT NULL,
    term_ja VARCHAR(200) NOT NULL,
    reading VARCHAR(200),
    meaning_vi TEXT,
    example_ja TEXT,
    example_reading TEXT,
    example_vi TEXT,
    sort_order INT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_cert_vocab_cert ON certificate_vocabulary(certificate_id, category_no, sort_order);

CREATE TABLE IF NOT EXISTS certificate_exam_questions (
    id SERIAL PRIMARY KEY,
    certificate_id INT NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,
    exam_year VARCHAR(10) NOT NULL,
    exam_round VARCHAR(20),
    question_no INT NOT NULL,
    question_ja TEXT NOT NULL,
    translation_vi TEXT NOT NULL,
    answer_correct BOOLEAN NOT NULL,
    explanation_vi TEXT NOT NULL,
    vocab_json JSONB NOT NULL DEFAULT '[]',
    sort_order INT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_cert_exam_cert ON certificate_exam_questions(certificate_id, sort_order);

VALUES ('kikaihozen3', 'cokhi', '機械系保全作業', 'Kỹ năng bảo trì cơ khí 3級')
ON CONFLICT (code) DO NOTHING;

-- Vocabulary entries
DO $$
DECLARE cert_id INT;
BEGIN
    SELECT id INTO cert_id FROM certificates WHERE code = 'kikaihozen3';
    DELETE FROM certificate_vocabulary WHERE certificate_id = cert_id;

END $$;

-- Exam questions
DO $$
DECLARE cert_id INT;
BEGIN
    SELECT id INTO cert_id FROM certificates WHERE code = 'kikaihozen3';
    DELETE FROM certificate_exam_questions WHERE certificate_id = cert_id;

END $$;
